CREATE OR REPLACE FUNCTION private.assert_collection_read_scope(p_cell_id uuid DEFAULT NULL::uuid, p_cell_name text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
declare
  v_profile_role text;
  v_profile_cell text;
  v_managed_cells text[];
  v_cell_from_id text;
  v_cell_from_name text;
  v_requested_cell text;
begin
  if auth.role() = 'service_role' then
    return;
  end if;

  if auth.uid() is null
     or not (
       public.has_permission('view_collection')
       or public.has_permission('register_production')
       or public.has_permission('view_traceability')
       or public.has_permission('view_dashboards')
     ) then
    raise exception 'COLLECTION_VIEW_PERMISSION_REQUIRED' using errcode = '42501';
  end if;

  select role, cell, coalesce(managed_cells, '{}'::text[])
    into v_profile_role, v_profile_cell, v_managed_cells
  from public.profiles
  where id = auth.uid()
    and active is true;

  if not found then
    raise exception 'ACTIVE_PROFILE_REQUIRED' using errcode = '42501';
  end if;

  if p_cell_id is not null then
    select name into v_cell_from_id
    from public.cells
    where id = p_cell_id;

    if not found then
      raise exception 'COLLECTION_CELL_NOT_FOUND' using errcode = '22023';
    end if;
  end if;

  if nullif(btrim(p_cell_name), '') is not null then
    select name into v_cell_from_name
    from public.cells
    where lower(btrim(name)) = lower(btrim(p_cell_name))
    order by active desc, name
    limit 1;

    if not found then
      raise exception 'COLLECTION_CELL_NOT_FOUND' using errcode = '22023';
    end if;
  end if;

  if v_cell_from_id is not null
     and v_cell_from_name is not null
     and lower(btrim(v_cell_from_id)) <> lower(btrim(v_cell_from_name)) then
    raise exception 'COLLECTION_CELL_FILTER_MISMATCH' using errcode = '22023';
  end if;

  v_requested_cell := coalesce(v_cell_from_id, v_cell_from_name);

  if v_requested_cell is not null then
    if not public.profile_can_access_cell(v_requested_cell) then
      raise exception 'COLLECTION_OUTSIDE_CELL_SCOPE' using errcode = '42501';
    end if;
    return;
  end if;

  -- Admins e perfis gerenciais sem escopo explícito podem consultar a visão
  -- global. Operadores e qualquer perfil já limitado a células devem filtrar.
  if v_profile_role = 'admin' then
    return;
  end if;

  if v_profile_role = 'operator'
     or array_length(v_managed_cells, 1) is not null
     or nullif(btrim(v_profile_cell), '') is not null then
    raise exception 'COLLECTION_CELL_SCOPE_REQUIRED' using errcode = '42501';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION private.validate_replacement_operator_session_v2(p_session_token text, p_device_id text, p_require_context boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
declare
  v_session public.operator_sessions%rowtype;
  v_operator public.operators%rowtype;
  v_cell public.cells%rowtype;
  v_machine public.production_machines%rowtype;
  v_now timestamptz := clock_timestamp();
begin
  if auth.uid() is null then
    return jsonb_build_object('success', false, 'reason_code', 'AUTH_REQUIRED', 'message', 'Autenticacao do sistema expirada.');
  end if;

  select session_row.*
  into v_session
  from public.operator_sessions session_row
  where session_row.token_hash = encode(extensions.digest(coalesce(p_session_token, ''), 'sha256'), 'hex')
    and session_row.auth_user_id = auth.uid()
    and session_row.device_id = btrim(coalesce(p_device_id, ''))
  order by session_row.started_at desc
  limit 1;

  if v_session.id is null then
    return jsonb_build_object('success', false, 'reason_code', 'SESSION_INVALID', 'message', 'Sessao operacional nao localizada para este dispositivo.');
  end if;

  select operator_row.*
  into v_operator
  from public.operators operator_row
  where operator_row.id = v_session.operator_id;

  if v_operator.id is null
     or v_operator.active is not true
     or coalesce(v_operator.login_enabled, true) is not true
     or v_operator.replacement_enabled is not true then
    return jsonb_build_object(
      'success', false,
      'reason_code', 'REPLACEMENT_ACCESS_DENIED',
      'message', 'Colaborador sem liberacao para realizar baixas de reposicao.'
    );
  end if;

  if p_require_context is not true then
    return jsonb_build_object('success', true, 'operator_id', v_operator.id);
  end if;

  if v_session.cell_id is null then
    return jsonb_build_object('success', false, 'reason_code', 'CONTEXT_REQUIRED', 'message', 'Selecione a celula e o posto de reposicao.');
  end if;

  select cell.* into v_cell
  from public.cells cell
  where cell.id = v_session.cell_id and cell.active is true;

  if v_cell.id is null or not exists (
    select 1
    from public.operator_cell_assignments assignment
    where assignment.operator_id = v_operator.id
      and assignment.cell_id = v_session.cell_id
      and assignment.active is true
      and assignment.valid_from <= v_now
      and (assignment.valid_until is null or assignment.valid_until > v_now)
  ) then
    return jsonb_build_object('success', false, 'reason_code', 'OPERATOR_UNAUTHORIZED', 'message', 'Colaborador nao autorizado para esta celula.');
  end if;

  if v_session.machine_id is not null then
    select machine.* into v_machine
    from public.production_machines machine
    where machine.id = v_session.machine_id;

    if v_machine.id is null
       or v_machine.active is not true
       or v_machine.allows_replacement is not true
       or lower(btrim(v_machine.cell_name)) <> lower(btrim(v_cell.name)) then
      return jsonb_build_object('success', false, 'reason_code', 'MACHINE_UNAUTHORIZED', 'message', 'Posto inativo ou nao habilitado para reposicao nesta celula.');
    end if;

    if exists (
      select 1
      from public.operator_machine_assignments assignment
      where assignment.operator_id = v_operator.id
        and assignment.active is true
        and assignment.valid_from <= v_now
        and (assignment.valid_until is null or assignment.valid_until > v_now)
    ) and not exists (
      select 1
      from public.operator_machine_assignments assignment
      where assignment.operator_id = v_operator.id
        and assignment.machine_id = v_session.machine_id
        and assignment.active is true
        and assignment.valid_from <= v_now
        and (assignment.valid_until is null or assignment.valid_until > v_now)
    ) then
      return jsonb_build_object('success', false, 'reason_code', 'OPERATOR_UNAUTHORIZED', 'message', 'Colaborador nao autorizado para este posto.');
    end if;
  end if;

  return jsonb_build_object(
    'success', true,
    'operator_id', v_operator.id,
    'cell_id', v_session.cell_id,
    'machine_id', v_session.machine_id
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_delete_operator(p_operator_id uuid, p_confirmation text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
DECLARE
  v_operator public.operators%ROWTYPE;
  v_actor_name text;
  v_actor_email text;
BEGIN
  IF auth.uid() IS NULL OR public.get_my_role() <> 'admin' THEN
    RAISE EXCEPTION 'Apenas administradores podem excluir operadores.';
  END IF;

  SELECT * INTO v_operator
  FROM public.operators
  WHERE id = p_operator_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Operador não encontrado.';
  END IF;

  IF btrim(COALESCE(p_confirmation, '')) <> v_operator.name THEN
    RAISE EXCEPTION 'Confirmação inválida. Digite exatamente o nome do operador.';
  END IF;

  SELECT name, email INTO v_actor_name, v_actor_email
  FROM public.profiles WHERE id = auth.uid();

  INSERT INTO public.system_audit_logs (
    user_id, user_name, user_email, user_role, action, entity,
    entity_id, entity_label, page, route, method, old_value, success
  ) VALUES (
    auth.uid(), v_actor_name, v_actor_email, 'admin', 'delete', 'operator',
    v_operator.id::text, v_operator.name, 'Gestão de Operadores', '/operadores',
    'RPC', jsonb_build_object('name', v_operator.name, 'login_name', v_operator.login_name), true
  );

  DELETE FROM public.operators WHERE id = p_operator_id;

  RETURN jsonb_build_object('success', true, 'deleted_id', p_operator_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_unlock_operator(p_operator_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.can_manage_operators() THEN
    RETURN jsonb_build_object('success', false, 'error', 'Sem permissão para desbloquear operadores.');
  END IF;

  UPDATE public.operators
  SET failed_login_count = 0,
      locked_until = NULL
  WHERE id = p_operator_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Operador não encontrado.');
  END IF;

  RETURN jsonb_build_object('success', true);
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_upsert_operator_v2(p_operator_id uuid, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
declare
  v_result jsonb;
  v_operator_id uuid;
  v_replacement_enabled boolean;
begin
  if auth.uid() is null or not public.can_manage_operators() then
    return jsonb_build_object('success', false, 'error', 'Sem permissao para gerenciar colaboradores.');
  end if;

  v_result := public.admin_upsert_operator(p_operator_id, coalesce(p_data, '{}'::jsonb));
  if coalesce((v_result ->> 'success')::boolean, false) is not true then
    return v_result;
  end if;

  v_operator_id := nullif(v_result #>> '{operator,id}', '')::uuid;
  if v_operator_id is null then
    return jsonb_build_object('success', false, 'error', 'O cadastro nao retornou um colaborador valido.');
  end if;

  if coalesce(p_data, '{}'::jsonb) ? 'replacement_enabled' then
    v_replacement_enabled := coalesce((p_data ->> 'replacement_enabled')::boolean, false);
    update public.operators
    set replacement_enabled = v_replacement_enabled
    where id = v_operator_id;
  else
    select operator_row.replacement_enabled
    into v_replacement_enabled
    from public.operators operator_row
    where operator_row.id = v_operator_id;
  end if;

  return jsonb_set(
    v_result,
    '{operator,replacement_enabled}',
    to_jsonb(coalesce(v_replacement_enabled, false)),
    true
  );
exception
  when invalid_text_representation then
    return jsonb_build_object('success', false, 'error', 'A liberacao para reposicao possui formato invalido.');
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_upsert_operator(p_operator_id uuid, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_operator public.operators%ROWTYPE;
  v_cell_ids uuid[];
  v_machine_ids uuid[];
  v_primary_cell_id uuid;
  v_primary_machine_id uuid;
  v_name text := btrim(COALESCE(p_data ->> 'name', ''));
  v_login text := lower(btrim(COALESCE(p_data ->> 'login_name', '')));
  v_registration text := NULLIF(btrim(COALESCE(p_data ->> 'registration', '')), '');
  v_shift text := NULLIF(btrim(COALESCE(p_data ->> 'shift', '')), '');
  v_active boolean := COALESCE((p_data ->> 'active')::boolean, true);
  v_primary_cell_name text;
  v_invalid_count integer;
BEGIN
  IF NOT public.can_manage_operators() THEN
    RETURN jsonb_build_object('success', false, 'error', 'Sem permissão para gerenciar operadores.');
  END IF;

  IF v_name = '' OR v_login = '' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Nome e login são obrigatórios.');
  END IF;

  IF v_login !~ '^[a-z0-9.]+$' THEN
    RETURN jsonb_build_object('success', false, 'error', 'O login aceita apenas letras minúsculas, números e pontos.');
  END IF;

  SELECT COALESCE(array_agg(DISTINCT value::uuid), ARRAY[]::uuid[])
  INTO v_cell_ids
  FROM jsonb_array_elements_text(COALESCE(p_data -> 'cell_ids', '[]'::jsonb));

  SELECT COALESCE(array_agg(DISTINCT value::uuid), ARRAY[]::uuid[])
  INTO v_machine_ids
  FROM jsonb_array_elements_text(COALESCE(p_data -> 'machine_ids', '[]'::jsonb));

  v_primary_cell_id := NULLIF(p_data ->> 'primary_cell_id', '')::uuid;
  v_primary_machine_id := NULLIF(p_data ->> 'primary_machine_id', '')::uuid;

  IF cardinality(v_cell_ids) = 0 OR v_primary_cell_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Vincule ao menos uma célula e defina a célula principal.');
  END IF;

  IF NOT (v_primary_cell_id = ANY(v_cell_ids)) THEN
    RETURN jsonb_build_object('success', false, 'error', 'A célula principal deve estar entre as células autorizadas.');
  END IF;

  SELECT count(*)
  INTO v_invalid_count
  FROM unnest(v_cell_ids) requested(cell_id)
  LEFT JOIN public.cells cell ON cell.id = requested.cell_id AND cell.active = true
  WHERE cell.id IS NULL;

  IF v_invalid_count > 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Uma ou mais células são inválidas ou estão inativas.');
  END IF;

  SELECT count(*)
  INTO v_invalid_count
  FROM unnest(v_machine_ids) requested(machine_id)
  LEFT JOIN public.production_machines machine ON machine.id = requested.machine_id AND machine.active = true
  LEFT JOIN public.cells cell
    ON lower(btrim(cell.name)) = lower(btrim(machine.cell_name))
   AND cell.id = ANY(v_cell_ids)
  WHERE machine.id IS NULL OR cell.id IS NULL;

  IF v_invalid_count > 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Uma máquina selecionada não pertence às células autorizadas.');
  END IF;

  IF v_primary_machine_id IS NOT NULL AND NOT (v_primary_machine_id = ANY(v_machine_ids)) THEN
    RETURN jsonb_build_object('success', false, 'error', 'A máquina principal deve estar entre as máquinas autorizadas.');
  END IF;

  SELECT name INTO v_primary_cell_name
  FROM public.cells
  WHERE id = v_primary_cell_id;

  IF p_operator_id IS NULL THEN
    IF v_registration IS NULL THEN
      RETURN jsonb_build_object('success', false, 'error', 'A matrícula é obrigatória para um novo operador.');
    END IF;

    INSERT INTO public.operators (
      name,
      role,
      active,
      registration,
      login_name,
      primary_cell,
      cells,
      shift,
      login_enabled,
      primary_cell_id,
      primary_machine_id
    )
    VALUES (
      v_name,
      'operator',
      v_active,
      v_registration,
      v_login,
      v_primary_cell_name,
      ARRAY(SELECT name FROM public.cells WHERE id = ANY(v_cell_ids) ORDER BY name),
      v_shift,
      true,
      v_primary_cell_id,
      v_primary_machine_id
    )
    RETURNING * INTO v_operator;
  ELSE
    UPDATE public.operators
    SET name = v_name,
        login_name = v_login,
        registration = COALESCE(v_registration, registration),
        primary_cell = v_primary_cell_name,
        cells = ARRAY(SELECT name FROM public.cells WHERE id = ANY(v_cell_ids) ORDER BY name),
        shift = v_shift,
        active = v_active,
        login_enabled = v_active,
        primary_cell_id = v_primary_cell_id,
        primary_machine_id = v_primary_machine_id,
        deactivated_at = CASE WHEN v_active THEN NULL ELSE COALESCE(deactivated_at, now()) END,
        deactivated_by = CASE WHEN v_active THEN NULL ELSE auth.uid() END
    WHERE id = p_operator_id
    RETURNING * INTO v_operator;

    IF v_operator.id IS NULL THEN
      RETURN jsonb_build_object('success', false, 'error', 'Operador não encontrado.');
    END IF;
  END IF;

  UPDATE public.operator_cell_assignments
  SET active = false,
      valid_until = now(),
      is_primary = false,
      updated_at = now()
  WHERE operator_id = v_operator.id
    AND active = true;

  INSERT INTO public.operator_cell_assignments (
    operator_id,
    cell_id,
    is_primary,
    active,
    valid_from,
    valid_until,
    assigned_by
  )
  SELECT
    v_operator.id,
    requested.cell_id,
    requested.cell_id = v_primary_cell_id,
    true,
    now(),
    NULL,
    auth.uid()
  FROM unnest(v_cell_ids) AS requested(cell_id);

  UPDATE public.operator_machine_assignments
  SET active = false,
      valid_until = now(),
      is_primary = false,
      updated_at = now()
  WHERE operator_id = v_operator.id
    AND active = true;

  INSERT INTO public.operator_machine_assignments (
    operator_id,
    machine_id,
    is_primary,
    active,
    valid_from,
    valid_until,
    assigned_by
  )
  SELECT
    v_operator.id,
    requested.machine_id,
    requested.machine_id = v_primary_machine_id,
    true,
    now(),
    NULL,
    auth.uid()
  FROM unnest(v_machine_ids) AS requested(machine_id);

  RETURN jsonb_build_object(
    'success', true,
    'operator', (
      to_jsonb(v_operator)
      - 'registration'
      - 'registration_normalized'
      - 'credential_hash'
    )
  );
EXCEPTION
  WHEN unique_violation THEN
    RETURN jsonb_build_object('success', false, 'error', 'Login ou matrícula já está em uso por outro operador.');
  WHEN invalid_text_representation THEN
    RETURN jsonb_build_object('success', false, 'error', 'Um dos vínculos informados possui formato inválido.');
END;
$function$

CREATE OR REPLACE FUNCTION public.advance_piece_stage(p_piece_id uuid, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_piece       production_pieces%ROWTYPE;
  v_user_id     uuid;
  v_role        text;
  v_to_stage    text;
  v_from_stage  text;
  v_operator_id uuid;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Autenticação necessária.');
  END IF;

  v_role := get_my_role();
  IF v_role NOT IN ('admin', 'manager', 'operator') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Permissão insuficiente.');
  END IF;

  SELECT * INTO v_piece FROM production_pieces WHERE id = p_piece_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Peça não encontrada.');
  END IF;

  IF v_piece.is_blocked THEN
    RETURN jsonb_build_object('success', false, 'error', 'Peça bloqueada: ' || COALESCE(v_piece.block_reason, 'sem motivo informado'));
  END IF;

  IF v_piece.status IN ('cancelled', 'shipped') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Peça com status ' || v_piece.status || ' não pode avançar etapas.');
  END IF;

  v_from_stage := v_piece.current_stage;
  v_to_stage   := COALESCE(NULLIF(p_payload->>'to_stage', ''), v_from_stage);
  v_operator_id := (p_payload->>'operator_id')::uuid;

  UPDATE production_pieces SET
    current_stage = v_to_stage,
    status = CASE
      WHEN v_to_stage = 'shipped'   THEN 'shipped'
      WHEN v_to_stage = 'completed' THEN 'completed'
      ELSE 'in_progress'
    END,
    updated_at = now()
  WHERE id = p_piece_id;

  INSERT INTO production_events (
    piece_id,
    traceability_code,
    production_order_id,
    lot_id,
    event_type,
    from_stage,
    to_stage,
    cell_name,
    device_id,
    operator_id,
    event_status,
    notes,
    metadata
  ) VALUES (
    v_piece.id,
    v_piece.traceability_code,
    v_piece.production_order_id,
    v_piece.lot_id,
    'stage_advance',
    v_from_stage,
    v_to_stage,
    p_payload->>'cell_name',
    p_payload->>'device_id',
    v_operator_id,
    'accepted',
    p_payload->>'notes',
    COALESCE(p_payload->'metadata', '{}'::jsonb)
  );

  RETURN jsonb_build_object(
    'success',       true,
    'piece_id',      v_piece.id,
    'from_stage',    v_from_stage,
    'to_stage',      v_to_stage,
    'new_status',    CASE
      WHEN v_to_stage = 'shipped'   THEN 'shipped'
      WHEN v_to_stage = 'completed' THEN 'completed'
      ELSE 'in_progress'
    END
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.approve_piece_replacement(p_order_id uuid, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_order public.replacement_orders%ROWTYPE;
  v_original public.production_pieces%ROWTYPE;
  v_lot public.production_lots%ROWTYPE;
  v_production_order public.production_orders%ROWTYPE;
  v_production_order_id uuid;
  v_replacement_piece_id uuid;
  v_replacement_uid text;
  v_internal_traceability text;
  v_barcode text;
  v_priority text := NULLIF(p_payload->>'priority', '');
  v_notes text := NULLIF(trim(p_payload->>'notes'), '');
  v_selected_cells jsonb := COALESCE(p_payload->'selected_cells', '[]'::jsonb);
  v_selected jsonb;
  v_approved_cells jsonb := '[]'::jsonb;
  v_route text[];
  v_route_codes text[] := '{}'::text[];
  v_completed_steps text[] := '{}'::text[];
  v_route_value text;
  v_step_code text;
  v_next_step text;
  v_cell public.cells%ROWTYPE;
  v_client_event_id text;
  v_entry_id uuid;
  v_reading_id uuid;
  v_operator_name text;
  v_shift text := COALESCE(NULLIF(p_payload->>'shift', ''), 'Reposição');
  v_entry_count integer := 0;
  v_order_status text;
  v_piece_status text;
BEGIN
  IF jsonb_typeof(v_selected_cells) <> 'array' THEN
    RAISE EXCEPTION 'selected_cells deve ser uma lista.';
  END IF;

  SELECT * INTO v_order
  FROM public.replacement_orders
  WHERE id = p_order_id
  FOR UPDATE;

  IF v_order.id IS NULL THEN
    RAISE EXCEPTION 'Ordem de reposição não encontrada.';
  END IF;

  IF v_order.replacement_piece_id IS NOT NULL
     AND v_order.status IN ('approved', 'released', 'in_production', 'completed') THEN
    RETURN jsonb_build_object(
      'success', true,
      'idempotent', true,
      'order_id', v_order.id,
      'status', v_order.status,
      'replacement_piece_id', v_order.replacement_piece_id,
      'replacement_barcode', v_order.replacement_barcode,
      'automatic_entries', v_order.approval_entry_count,
      'approved_cells', v_order.approved_cells
    );
  END IF;

  IF v_order.status NOT IN ('requested', 'under_review') THEN
    RAISE EXCEPTION 'Status atual inválido para aprovação: %', v_order.status;
  END IF;

  SELECT * INTO v_original
  FROM public.production_pieces
  WHERE id = v_order.original_piece_id
  FOR UPDATE;

  IF v_original.id IS NULL THEN
    RAISE EXCEPTION 'Peça original não encontrada.';
  END IF;
  IF v_original.lot_id IS NULL THEN
    RAISE EXCEPTION 'A peça original não possui lote vinculado.';
  END IF;

  SELECT * INTO v_lot FROM public.production_lots WHERE id = v_original.lot_id;
  v_production_order_id := COALESCE(v_original.production_order_id, v_lot.production_order_id, v_lot.order_id);
  SELECT * INTO v_production_order
  FROM public.production_orders
  WHERE id = v_production_order_id;

  v_barcode := COALESCE(
    NULLIF(v_order.replacement_barcode, ''),
    NULLIF(v_original.traceability_code, ''),
    NULLIF(v_original.piece_uid, ''),
    NULLIF(v_original.piece_code, '')
  );
  IF v_barcode IS NULL THEN
    RAISE EXCEPTION 'A peça original não possui código de barras rastreável.';
  END IF;

  v_route := COALESCE(v_original.route_steps, '{}'::text[]);
  IF cardinality(v_route) = 0 THEN
    v_route := ARRAY[]::text[];
    IF COALESCE(v_original.requires_cut, false) THEN v_route := array_append(v_route, 'cut'); END IF;
    IF COALESCE(v_original.requires_edge, false) THEN v_route := array_append(v_route, 'edge'); END IF;
    IF COALESCE(v_original.requires_cnc, false) THEN v_route := array_append(v_route, 'cnc'); END IF;
    IF COALESCE(v_original.requires_joinery, false) THEN v_route := array_append(v_route, 'joinery'); END IF;
    IF COALESCE(v_original.requires_separation, false) THEN v_route := array_append(v_route, 'separation'); END IF;
    IF COALESCE(v_original.requires_packaging, false) THEN v_route := array_append(v_route, 'packaging'); END IF;
  END IF;

  FOREACH v_route_value IN ARRAY v_route LOOP
    v_step_code := public.normalize_replacement_step_code(v_route_value);
    IF v_step_code IS NOT NULL AND NOT (v_step_code = ANY(v_route_codes)) THEN
      v_route_codes := array_append(v_route_codes, v_step_code);
    END IF;
  END LOOP;

  IF cardinality(v_route_codes) = 0 THEN
    v_route_codes := ARRAY['cut'];
    v_route := ARRAY['cut'];
  END IF;

  v_replacement_uid := v_barcode || '.REP.' || upper(substr(replace(v_order.id::text, '-', ''), 1, 8));
  v_internal_traceability := v_replacement_uid;

  INSERT INTO public.production_pieces (
    piece_uid, piece_code, traceability_code, piece_name, description,
    production_order_id, lot_id, lot_item_id, item_id,
    legacy_lot_item_id, legacy_production_lot_item_id,
    sequence_number, total_in_lot, is_active,
    module_name, environment, environment_name,
    material, thickness, color, width, height, length, grain_direction,
    edge_front, edge_back, edge_left, edge_right,
    requires_cut, requires_edge, requires_cnc, requires_joinery,
    requires_separation, requires_packaging,
    current_stage, status, source_origin, is_rework, original_piece_id,
    is_replacement, production_status, replacement_status,
    route_template_id, route_steps, completed_steps,
    lot_code, order_number, customer_name, pcp_import_batch_id, created_by
  ) VALUES (
    v_replacement_uid, v_barcode, v_internal_traceability,
    v_original.piece_name, v_original.description,
    v_production_order_id, v_original.lot_id,
    v_original.lot_item_id, v_original.item_id,
    v_original.legacy_lot_item_id, v_original.legacy_production_lot_item_id,
    v_original.sequence_number, v_original.total_in_lot, true,
    v_original.module_name, v_original.environment, v_original.environment_name,
    v_original.material, v_original.thickness, v_original.color,
    v_original.width, v_original.height, v_original.length, v_original.grain_direction,
    v_original.edge_front, v_original.edge_back, v_original.edge_left, v_original.edge_right,
    v_original.requires_cut, v_original.requires_edge, v_original.requires_cnc,
    v_original.requires_joinery, v_original.requires_separation, v_original.requires_packaging,
    v_route_codes[1], 'in_progress', 'rework', true, v_original.id,
    true, 'approved', 'in_production',
    v_original.route_template_id, v_route, '{}'::text[],
    COALESCE(v_original.lot_code, v_order.lot_code, v_lot.lot_code),
    COALESCE(v_original.order_number, v_order.order_number, v_production_order.order_number, v_production_order.order_code),
    COALESCE(v_original.customer_name, v_order.customer_name, v_production_order.customer_name),
    v_original.pcp_import_batch_id, v_user_id
  )
  RETURNING id INTO v_replacement_piece_id;

  -- O mesmo código físico passa a resolver a peça substituta. A peça original
  -- continua preservada para auditoria e mantém seus snapshots históricos.
  UPDATE public.production_tags
  SET active = false, updated_at = now()
  WHERE upper(tag_value) = upper(v_barcode)
    AND active IS TRUE;

  INSERT INTO public.production_tags (
    lot_id, item_id, piece_id, tag_value, tag_type, tag_format,
    barcode_value, active, created_at, updated_at
  ) VALUES (
    v_original.lot_id,
    COALESCE(v_original.legacy_production_lot_item_id, v_original.lot_item_id),
    v_replacement_piece_id,
    v_barcode,
    'barcode',
    'custom',
    v_barcode,
    true,
    now(),
    now()
  );

  v_operator_name := COALESCE(
    NULLIF(p_payload->>'operator_name', ''),
    NULLIF(v_order.operator_name, ''),
    'Aprovação de reposição'
  );

  FOR v_selected IN
    SELECT value FROM jsonb_array_elements(v_selected_cells)
  LOOP
    v_step_code := public.normalize_replacement_step_code(v_selected->>'step_code');

    SELECT * INTO v_cell
    FROM public.cells
    WHERE id = NULLIF(v_selected->>'cell_id', '')::uuid
      AND active IS TRUE;

    IF v_cell.id IS NULL THEN
      RAISE EXCEPTION 'Célula selecionada não existe ou está inativa.';
    END IF;

    v_step_code := COALESCE(v_step_code, public.normalize_replacement_step_code(v_cell.name));
    IF NOT (v_step_code = ANY(v_route_codes)) THEN
      RAISE EXCEPTION 'A etapa % da célula % não pertence à rota da peça.', v_step_code, v_cell.name;
    END IF;
    IF NOT public.replacement_cell_matches_step(v_cell.name, v_step_code) THEN
      RAISE EXCEPTION 'A célula % não corresponde à etapa %.', v_cell.name, v_step_code;
    END IF;

    IF v_step_code = ANY(v_completed_steps) THEN
      CONTINUE;
    END IF;

    v_client_event_id := 'replacement:' || v_order.id::text || ':' || v_step_code;

    IF EXISTS (
      SELECT 1 FROM public.production_collection_events
      WHERE client_event_id = v_client_event_id
    ) THEN
      v_completed_steps := array_append(v_completed_steps, v_step_code);
      CONTINUE;
    END IF;

    INSERT INTO public.production_entries (
      date, shift, cell, hour, produced, target, scrap, downtime,
      operator, operator_id, operator_name_snapshot, notes,
      order_id, production_order_id, lot_id,
      order_number, lot_code, customer_name, environment_name,
      product_code, product_name, product_description,
      step_code, process_step, operation_name,
      entry_mode, source, approval_status, client_event_id,
      is_rework, rework_reason, pcp_import_batch_id,
      unit_of_measure, metric_unit, metric_unit_label, metric_name,
      created_by, created_at
    ) VALUES (
      current_date, v_shift, v_cell.name, to_char(now(), 'HH24:MI'),
      1, 0, 0, 0,
      v_operator_name, v_order.operator_id, v_operator_name,
      'Baixa por reposição — ' || COALESCE(v_order.replacement_code, v_order.id::text)
        || ' — Código ' || v_barcode,
      v_production_order_id, v_production_order_id,
      v_original.lot_id,
      COALESCE(v_order.order_number, v_original.order_number, v_production_order.order_number, v_production_order.order_code),
      COALESCE(v_order.lot_code, v_original.lot_code, v_lot.lot_code),
      COALESCE(v_order.customer_name, v_original.customer_name, v_production_order.customer_name),
      COALESCE(v_order.environment_name, v_original.environment_name, v_original.environment),
      v_barcode, v_original.piece_name, v_original.description,
      v_step_code, v_step_code, v_step_code,
      'automatic_replacement', 'replacement_approval', 'valid', v_client_event_id,
      true, v_order.reason, v_original.pcp_import_batch_id,
      'pecas', 'pieces', 'Peças', 'Baixa por reposição',
      v_user_id, now()
    )
    RETURNING id INTO v_entry_id;

    INSERT INTO public.production_stage_readings (
      client_event_id, tag_value, tag_type, reader_type,
      station_name, cell_name, operator, operator_name_snapshot,
      user_id, operator_id, shift, date, hour,
      item_id, piece_id, lot_id, production_order_id,
      step_name, operation_name, quantity, status, event_type,
      notes, lot_code, order_number, customer_name, environment_name,
      piece_code, production_entry_id, production_cycle,
      entry_type, traceability_type, is_manual, unit_of_measure,
      general_lot_code, created_at
    ) VALUES (
      v_client_event_id, v_barcode, 'barcode', 'api',
      'Aprovação de Reposição', v_cell.name, v_operator_name, v_operator_name,
      v_user_id, v_order.operator_id, v_shift, current_date, to_char(now(), 'HH24:MI'),
      COALESCE(v_original.legacy_production_lot_item_id, v_original.lot_item_id),
      v_replacement_piece_id, v_original.lot_id, v_production_order_id,
      v_step_code, v_step_code, 1, 'approved', 'replacement_approval',
      'Baixa por reposição — ' || COALESCE(v_order.replacement_code, v_order.id::text),
      COALESCE(v_order.lot_code, v_original.lot_code, v_lot.lot_code),
      COALESCE(v_order.order_number, v_original.order_number, v_production_order.order_number, v_production_order.order_code),
      COALESCE(v_order.customer_name, v_original.customer_name, v_production_order.customer_name),
      COALESCE(v_order.environment_name, v_original.environment_name, v_original.environment),
      v_barcode, v_entry_id, 1,
      'baixa_reposicao', 'unitaria', false, 'pecas',
      v_order.general_lot_code, now()
    )
    RETURNING id INTO v_reading_id;

    INSERT INTO public.production_collection_events (
      client_event_id, raw_value, normalized_value, reader_type,
      operator_id, operator_name, operator_name_snapshot, cell_id, cell_name,
      shift, shift_snapshot, date, hour, status, result_status,
      reading_id, production_entry_id, lot_id, production_order_id,
      payload, result_payload, created_at_client, processed_at,
      registration, operation_name, lot_code, order_number,
      customer_name, environment_name, piece_code, piece_id,
      station_name, station_name_snapshot, pcp_import_batch_id,
      entry_type, traceability_type, is_manual, unit_of_measure,
      general_lot_code, created_at, updated_at
    ) VALUES (
      v_client_event_id, v_barcode, v_barcode, 'api',
      v_order.operator_id, v_operator_name, v_operator_name,
      v_cell.id, v_cell.name,
      v_shift, v_shift, current_date, to_char(now(), 'HH24:MI'),
      'synced', 'approved',
      v_reading_id, v_entry_id, v_original.lot_id, v_production_order_id,
      jsonb_build_object(
        'source', 'replacement_approval',
        'replacement_order_id', v_order.id,
        'replacement_code', v_order.replacement_code,
        'barcode', v_barcode,
        'cell_id', v_cell.id,
        'cell_name', v_cell.name,
        'step_code', v_step_code
      ),
      jsonb_build_object(
        'success', true,
        'status', 'approved',
        'message', 'Baixa por reposição',
        'entry_type', 'baixa_reposicao',
        'source', 'replacement_approval',
        'replacement_order_id', v_order.id,
        'replacement_code', v_order.replacement_code,
        'replacement_piece_id', v_replacement_piece_id,
        'barcode', v_barcode,
        'cell_id', v_cell.id,
        'cell_name', v_cell.name,
        'step_code', v_step_code
      ),
      now(), now(),
      'REPOSIÇÃO', v_step_code,
      COALESCE(v_order.lot_code, v_original.lot_code, v_lot.lot_code),
      COALESCE(v_order.order_number, v_original.order_number, v_production_order.order_number, v_production_order.order_code),
      COALESCE(v_order.customer_name, v_original.customer_name, v_production_order.customer_name),
      COALESCE(v_order.environment_name, v_original.environment_name, v_original.environment),
      v_barcode, v_replacement_piece_id,
      'Aprovação de Reposição', 'Aprovação de Reposição', v_original.pcp_import_batch_id,
      'baixa_reposicao', 'unitaria', false, 'pecas',
      v_order.general_lot_code, now(), now()
    );

    v_completed_steps := array_append(v_completed_steps, v_step_code);
    v_entry_count := v_entry_count + 1;
    v_approved_cells := v_approved_cells || jsonb_build_array(jsonb_build_object(
      'cell_id', v_cell.id,
      'cell_name', v_cell.name,
      'step_code', v_step_code,
      'step_name', COALESCE(v_selected->>'step_name', v_cell.name),
      'client_event_id', v_client_event_id,
      'reading_id', v_reading_id,
      'production_entry_id', v_entry_id,
      'approved_at', now()
    ));
  END LOOP;

  v_next_step := NULL;
  FOREACH v_route_value IN ARRAY v_route_codes LOOP
    IF NOT (v_route_value = ANY(v_completed_steps)) THEN
      v_next_step := v_route_value;
      EXIT;
    END IF;
  END LOOP;

  v_piece_status := CASE WHEN v_next_step IS NULL THEN 'completed' ELSE 'in_progress' END;
  v_order_status := CASE WHEN v_next_step IS NULL THEN 'completed' ELSE 'in_production' END;

  UPDATE public.production_pieces
  SET completed_steps = v_completed_steps,
      current_stage = COALESCE(v_next_step, 'Concluída'),
      status = v_piece_status,
      production_status = CASE WHEN v_next_step IS NULL THEN 'completed' ELSE 'approved' END,
      replacement_status = CASE WHEN v_next_step IS NULL THEN 'replaced' ELSE 'in_production' END,
      updated_at = now()
  WHERE id = v_replacement_piece_id;

  UPDATE public.production_pieces
  SET replacement_status = CASE WHEN v_next_step IS NULL THEN 'replaced' ELSE 'in_production' END,
      status = CASE WHEN v_next_step IS NULL THEN 'replaced' ELSE status END,
      updated_at = now()
  WHERE id = v_original.id;

  UPDATE public.replacement_orders
  SET status = v_order_status,
      replacement_piece_id = v_replacement_piece_id,
      replacement_barcode = v_barcode,
      approver_id = v_user_id,
      approved_at = now(),
      released_at = CASE WHEN v_next_step IS NULL THEN released_at ELSE COALESCE(released_at, now()) END,
      completed_at = CASE WHEN v_next_step IS NULL THEN now() ELSE completed_at END,
      priority = COALESCE(v_priority, priority),
      notes = COALESCE(v_notes, notes),
      approved_cells = v_approved_cells,
      approval_entry_count = v_entry_count,
      updated_at = now()
  WHERE id = p_order_id;

  IF v_next_step IS NULL THEN
    UPDATE public.quality_nonconformities
    SET status = 'closed', closed_at = now(), closed_by = v_user_id
    WHERE related_replacement_id = p_order_id
      AND status <> 'closed';
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'order_id', p_order_id,
    'status', v_order_status,
    'replacement_piece_id', v_replacement_piece_id,
    'replacement_uid', v_replacement_uid,
    'replacement_barcode', v_barcode,
    'automatic_entries', v_entry_count,
    'approved_cells', v_approved_cells,
    'completed_steps', to_jsonb(v_completed_steps),
    'next_step', v_next_step,
    'message', CASE
      WHEN v_entry_count > 0 THEN 'Reposição aprovada com baixas automáticas.'
      ELSE 'Reposição aprovada e devolvida à fila produtiva.'
    END
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.audit_table_changes()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
DECLARE
  user_profile RECORD;
  action_name text;
  old_val jsonb := NULL;
  new_val jsonb := NULL;
BEGIN
  -- Busca dados do usuário logado
  SELECT name, email, role INTO user_profile
  FROM profiles WHERE id = auth.uid() LIMIT 1;

  -- Determina ação
  action_name := TG_OP;  -- INSERT, UPDATE, DELETE

  IF TG_OP = 'DELETE' THEN
    old_val := to_jsonb(OLD);
  ELSIF TG_OP = 'UPDATE' THEN
    old_val := to_jsonb(OLD);
    new_val := to_jsonb(NEW);
  ELSIF TG_OP = 'INSERT' THEN
    new_val := to_jsonb(NEW);
  END IF;

  INSERT INTO system_audit_logs (
    user_id, user_name, user_email, user_role,
    action, entity, entity_id,
    old_value, new_value,
    metadata, created_at
  ) VALUES (
    auth.uid(),
    user_profile.name,
    user_profile.email,
    user_profile.role,
    lower(action_name),
    TG_TABLE_NAME,
    CASE WHEN TG_OP = 'DELETE' THEN OLD.id::text ELSE NEW.id::text END,
    old_val,
    new_val,
    jsonb_build_object('trigger', true, 'table', TG_TABLE_NAME),
    now()
  );

  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.authorize_special_release(p_piece_id uuid, p_stage text, p_reason text, p_justification text, p_impact text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_piece record;
  v_user_id uuid;
  v_role text;
  v_new_completed_steps text[];
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Autenticação necessária.');
  END IF;

  v_role := public.get_my_role();
  IF v_role NOT IN ('admin', 'manager') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Apenas Administradores ou Gestores podem autorizar Liberação Especial.');
  END IF;

  SELECT * INTO v_piece FROM public.production_pieces WHERE id = p_piece_id;
  IF v_piece.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Peça não encontrada.');
  END IF;

  -- Registrar na tabela de exceções
  INSERT INTO public.flow_exceptions (
    piece_id, skipped_stage, reason, justification, impact, authorized_by
  ) VALUES (
    p_piece_id, p_stage, p_reason, p_justification, p_impact, v_user_id
  );

  -- Adicionar etapa liberada ao completed_steps da peça
  IF NOT (p_stage = ANY(v_piece.completed_steps)) THEN
    v_new_completed_steps := array_append(v_piece.completed_steps, p_stage);
  ELSE
    v_new_completed_steps := v_piece.completed_steps;
  END IF;

  UPDATE public.production_pieces SET
    completed_steps = v_new_completed_steps,
    is_blocked = false,
    block_reason = NULL,
    updated_at = now()
  WHERE id = p_piece_id;

  -- Gravar evento de correção
  INSERT INTO public.production_events (
    piece_id, traceability_code, production_order_id, lot_id,
    event_type, from_stage, to_stage, event_status, notes
  ) VALUES (
    v_piece.id, v_piece.traceability_code, v_piece.production_order_id, v_piece.lot_id,
    'correction', v_piece.current_stage, p_stage, 'accepted', 'Liberação Especial: ' || p_justification
  );

  RETURN jsonb_build_object('success', true, 'piece_id', p_piece_id, 'stage_released', p_stage);
END;
$function$

CREATE OR REPLACE FUNCTION public.block_external_email_group_member()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if new.profile_id is null or new.external_email is not null then
    raise exception 'Selecione um usuário cadastrado para o grupo de relatórios.';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.block_piece(p_piece_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_piece    production_pieces%ROWTYPE;
  v_user_id  uuid;
  v_role     text;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Autenticação necessária.');
  END IF;

  v_role := get_my_role();
  IF v_role NOT IN ('admin', 'manager') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Apenas admin ou manager podem bloquear peças.');
  END IF;

  IF TRIM(COALESCE(p_reason, '')) = '' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Motivo de bloqueio é obrigatório.');
  END IF;

  SELECT * INTO v_piece FROM production_pieces WHERE id = p_piece_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Peça não encontrada.');
  END IF;

  UPDATE production_pieces SET
    is_blocked   = true,
    block_reason = p_reason,
    blocked_at   = now(),
    blocked_by   = v_user_id,
    status       = 'blocked',
    updated_at   = now()
  WHERE id = p_piece_id;

  INSERT INTO production_events (
    piece_id, traceability_code, production_order_id, lot_id,
    event_type, from_stage, to_stage, event_status, notes
  ) VALUES (
    v_piece.id, v_piece.traceability_code, v_piece.production_order_id, v_piece.lot_id,
    'block', v_piece.current_stage, v_piece.current_stage, 'accepted', p_reason
  );

  RETURN jsonb_build_object(
    'success',      true,
    'piece_id',     v_piece.id,
    'piece_uid',    v_piece.piece_uid,
    'block_reason', p_reason
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.calcular_integridade_do_lote(p_lot_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if auth.role() <> 'service_role'
     and not (
       public.has_permission('manage_lot_integrity')
       or public.has_permission('view_integrity_logs')
       or public.has_permission('view_traceability')
       or public.has_permission('view_pcp')
     ) then
    raise exception 'LOT_INTEGRITY_PERMISSION_REQUIRED' using errcode = '42501';
  end if;

  return public.calcular_integridade_do_lote_impl(p_lot_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.calculate_lot_status(p_lot_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
DECLARE
  v_total_items integer;
  v_completed   integer;
  v_scrap       integer;
  v_blocked     integer;
  v_in_progress integer;
  v_result      text;
BEGIN
  SELECT
    COUNT(*),
    COUNT(*) FILTER (WHERE status = 'completed'),
    COUNT(*) FILTER (WHERE status = 'scrap'),
    COUNT(*) FILTER (WHERE status = 'blocked'),
    COUNT(*) FILTER (WHERE status = 'in_progress')
  INTO v_total_items, v_completed, v_scrap, v_blocked, v_in_progress
  FROM lot_items
  WHERE lot_id = p_lot_id;

  IF v_total_items = 0 THEN RETURN 'released'; END IF;
  IF v_blocked > 0 THEN RETURN 'blocked'; END IF;
  IF v_completed = v_total_items THEN RETURN 'completed'; END IF;
  IF v_in_progress > 0 THEN RETURN 'in_progress'; END IF;
  IF v_completed > 0 THEN RETURN 'partial'; END IF;
  RETURN 'planned';
END;
$function$

CREATE OR REPLACE FUNCTION public.cancel_customer_cover(p_cover_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_operator uuid := auth.uid();
BEGIN
  IF v_operator IS NULL OR public.get_my_role() NOT IN ('admin','manager') THEN
    RAISE EXCEPTION 'Permissão insuficiente para cancelar capa de cliente.' USING ERRCODE = '42501';
  END IF;

  UPDATE public.customer_covers
  SET status = 'cancelled', notes = COALESCE(notes, '') || E'\nCancelado: ' || p_reason
  WHERE id = p_cover_id;

  -- Desvincular lotes para que possam ser reagrupados se necessário
  UPDATE public.production_lots
  SET customer_cover_id = NULL
  WHERE customer_cover_id = p_cover_id;

  -- Registrar evento
  INSERT INTO public.customer_cover_events (cover_id, event_type, operator_id, metadata)
  VALUES (p_cover_id, 'cancelled', v_operator, jsonb_build_object('reason', p_reason));

  RETURN jsonb_build_object('success', true);
END;
$function$

CREATE OR REPLACE FUNCTION public.cancel_piece(p_piece_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_piece   production_pieces%ROWTYPE;
  v_user_id uuid;
  v_role    text;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Autenticação necessária.');
  END IF;

  v_role := get_my_role();
  IF v_role NOT IN ('admin', 'manager') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Apenas admin ou manager podem cancelar peças.');
  END IF;

  IF TRIM(COALESCE(p_reason, '')) = '' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Motivo de cancelamento é obrigatório.');
  END IF;

  SELECT * INTO v_piece FROM production_pieces WHERE id = p_piece_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Peça não encontrada.');
  END IF;

  IF v_piece.status = 'shipped' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Peça já expedida não pode ser cancelada.');
  END IF;

  UPDATE production_pieces SET
    status     = 'cancelled',
    is_blocked = true,
    block_reason = 'CANCELADA: ' || p_reason,
    updated_at = now()
  WHERE id = p_piece_id;

  INSERT INTO production_events (
    piece_id, traceability_code, production_order_id, lot_id,
    event_type, from_stage, to_stage, event_status, notes
  ) VALUES (
    v_piece.id, v_piece.traceability_code, v_piece.production_order_id, v_piece.lot_id,
    'cancel', v_piece.current_stage, 'cancelled', 'accepted', p_reason
  );

  RETURN jsonb_build_object(
    'success',  true,
    'piece_id', v_piece.id,
    'piece_uid', v_piece.piece_uid,
    'reason',   p_reason
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.canonical_stage_label(p_stage text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
  v_str text := LOWER(TRIM(COALESCE(p_stage, '')));
BEGIN
  IF v_str IN ('cut', 'corte') THEN RETURN 'Corte'; END IF;
  IF v_str IN ('edge', 'borda', 'bordo') THEN RETURN 'Borda'; END IF;
  IF v_str IN ('drill', 'furacao', 'furação') THEN RETURN 'Furação'; END IF;
  IF v_str IN ('cnc', 'usinagem cnc', 'usinagem') THEN RETURN 'Usinagem CNC'; END IF;
  IF v_str IN ('joinery', 'marcenaria') THEN RETURN 'Marcenaria'; END IF;
  IF v_str IN ('separation', 'separacao', 'separação') THEN RETURN 'Separação'; END IF;
  IF v_str IN ('packaging', 'embalagem') THEN RETURN 'Embalagem'; END IF;
  IF v_str IN ('shipping', 'expedicao', 'expedição') THEN RETURN 'Expedição'; END IF;
  IF v_str IN ('created', 'criada') THEN RETURN 'Criada'; END IF;
  IF v_str IN ('completed', 'concluida', 'concluída') THEN RETURN 'Concluída'; END IF;
  RETURN INITCAP(v_str);
END;
$function$

CREATE OR REPLACE FUNCTION public.capacity_test_ack_runner_stopped(p_test_run_id uuid, p_runner_instance_id uuid, p_stop_token text, p_project_ref text, p_environment text)
 RETURNS public.capacity_test_runs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  run_row public.capacity_test_runs%rowtype;
  supplied_hash text;
begin
  if coalesce(auth.jwt() ->> 'role', '') <> 'service_role' then
    raise exception 'A confirmação de parada exige service_role.' using errcode = '42501';
  end if;
  if p_runner_instance_id is null then
    raise exception 'runner_instance_id é obrigatório.' using errcode = '22023';
  end if;
  if coalesce(p_stop_token, '') !~ '^[0-9a-f]{64}$' then
    raise exception 'stop_token inválido.' using errcode = '22023';
  end if;
  supplied_hash := encode(extensions.digest(p_stop_token, 'sha256'), 'hex');

  select * into run_row
  from public.capacity_test_runs
  where id = p_test_run_id
  for update;

  if not found then
    raise exception 'Execução de teste não localizada.' using errcode = 'P0002';
  end if;
  if run_row.is_test is distinct from true
     or run_row.project_ref = 'uozuzdfvnufsjsonswag'
     or run_row.project_ref is distinct from p_project_ref
     or run_row.environment is distinct from p_environment
     or run_row.environment not in ('development', 'staging', 'supabase_branch') then
    raise exception 'A execução não pertence ao ambiente isolado de teste atual.' using errcode = '42501';
  end if;
  if run_row.runner_instance_id is distinct from p_runner_instance_id
     or run_row.runner_stop_token_hash is distinct from supplied_hash then
    raise exception 'A confirmação não pertence ao runner desta execução.' using errcode = '42501';
  end if;

  if run_row.runner_stopped_at is not null then
    return run_row;
  end if;

  update public.capacity_test_runs
  set runner_stopped_at = clock_timestamp(),
      state_version = state_version + 1,
      updated_at = clock_timestamp()
  where id = p_test_run_id
  returning * into run_row;

  return run_row;
end;
$function$

CREATE OR REPLACE FUNCTION public.capacity_test_apply_command(p_test_run_id uuid, p_command text, p_idempotency_key text, p_expected_state_version bigint DEFAULT NULL::bigint, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS public.capacity_test_runs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  run_row public.capacity_test_runs%rowtype;
  next_status text;
  existing_command public.capacity_test_commands%rowtype;
begin
  if not public.capacity_test_is_admin() then
    raise exception 'Apenas administradores ativos podem controlar testes de capacidade.' using errcode = '42501';
  end if;

  if nullif(btrim(p_idempotency_key), '') is null then
    raise exception 'idempotency_key é obrigatório.' using errcode = '22023';
  end if;

  select * into existing_command
  from public.capacity_test_commands
  where test_run_id = p_test_run_id and idempotency_key = p_idempotency_key;

  if found then
    select * into run_row from public.capacity_test_runs where id = p_test_run_id;
    return run_row;
  end if;

  select * into run_row
  from public.capacity_test_runs
  where id = p_test_run_id
  for update;

  if not found then
    raise exception 'Execução de teste não localizada.' using errcode = 'P0002';
  end if;

  if p_expected_state_version is not null and run_row.state_version <> p_expected_state_version then
    raise exception 'Comando concorrente detectado. Estado esperado %, estado atual %.', p_expected_state_version, run_row.state_version using errcode = '40001';
  end if;

  next_status := case p_command
    when 'prepare' then case when run_row.status in ('draft', 'failed') then 'preparing' end
    when 'release' then case when run_row.status = 'preparing' and coalesce((run_row.preflight ->> 'passed')::boolean, false) then 'ready' end
    when 'start' then case when run_row.status = 'ready' then 'running' end
    when 'pause' then case when run_row.status = 'running' then 'paused' end
    when 'resume' then case when run_row.status = 'paused' then 'running' end
    when 'stop' then case when run_row.status in ('running', 'paused') then 'cancelling' end
    when 'cancel' then case when run_row.status in ('draft', 'preparing', 'ready', 'running', 'paused', 'cancelling') then 'cancelled' end
    when 'finish' then case when run_row.status in ('running', 'paused', 'cancelling') then 'completed' end
    when 'repeat' then case when run_row.status in ('completed', 'cancelled', 'failed') then 'ready' end
    when 'report' then run_row.status
    when 'clean' then case when run_row.status in ('draft', 'ready', 'completed', 'cancelled', 'failed') then 'cleaning' end
  end;

  if next_status is null then
    raise exception 'Transição inválida: comando % no estado %.', p_command, run_row.status using errcode = '22023';
  end if;

  insert into public.capacity_test_commands (
    test_run_id, command, idempotency_key, expected_state_version,
    previous_status, resulting_status, requested_by, payload
  ) values (
    run_row.id, p_command, p_idempotency_key, p_expected_state_version,
    run_row.status, next_status, auth.uid(), coalesce(p_payload, '{}'::jsonb)
  );

  update public.capacity_test_runs
  set status = next_status,
      state_version = state_version + 1,
      started_at = case when p_command = 'start' then coalesce(started_at, now()) else started_at end,
      paused_at = case when p_command = 'pause' then now() when p_command = 'resume' then null else paused_at end,
      cancelled_at = case when p_command = 'cancel' then now() else cancelled_at end,
      finished_at = case when p_command = 'finish' then now() else finished_at end,
      updated_at = now()
  where id = run_row.id
  returning * into run_row;

  return run_row;
end;
$function$

CREATE OR REPLACE FUNCTION public.capacity_test_claim_runner(p_test_run_id uuid, p_runner_instance_id uuid, p_stop_token_hash text, p_project_ref text, p_environment text)
 RETURNS public.capacity_test_runs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  run_row public.capacity_test_runs%rowtype;
begin
  if coalesce(auth.jwt() ->> 'role', '') <> 'service_role' then
    raise exception 'A lease do runner exige service_role.' using errcode = '42501';
  end if;
  if p_runner_instance_id is null then
    raise exception 'runner_instance_id é obrigatório.' using errcode = '22023';
  end if;
  if coalesce(p_stop_token_hash, '') !~ '^[0-9a-f]{64}$' then
    raise exception 'stop_token_hash inválido.' using errcode = '22023';
  end if;

  select * into run_row
  from public.capacity_test_runs
  where id = p_test_run_id
  for update;

  if not found then
    raise exception 'Execução de teste não localizada.' using errcode = 'P0002';
  end if;
  if run_row.is_test is distinct from true
     or run_row.project_ref = 'uozuzdfvnufsjsonswag'
     or run_row.project_ref is distinct from p_project_ref
     or run_row.environment is distinct from p_environment
     or run_row.environment not in ('development', 'staging', 'supabase_branch') then
    raise exception 'A execução não pertence ao ambiente isolado de teste atual.' using errcode = '42501';
  end if;
  if run_row.status <> 'ready' then
    raise exception 'A lease só pode ser adquirida no estado ready; estado atual: %.', run_row.status using errcode = '22023';
  end if;

  if run_row.runner_instance_id is not null and run_row.runner_stopped_at is null then
    if run_row.runner_instance_id = p_runner_instance_id
       and run_row.runner_stop_token_hash = p_stop_token_hash then
      return run_row;
    end if;
    raise exception 'Esta execução já possui um runner ativo.' using errcode = '55006';
  end if;

  update public.capacity_test_runs
  set runner_instance_id = p_runner_instance_id,
      runner_stop_token_hash = p_stop_token_hash,
      runner_claimed_at = clock_timestamp(),
      runner_stopped_at = null,
      state_version = state_version + 1,
      updated_at = clock_timestamp()
  where id = p_test_run_id
  returning * into run_row;

  return run_row;
end;
$function$

CREATE OR REPLACE FUNCTION public.capacity_test_cleanup_scenario(p_test_run_id uuid, p_confirmation text, p_project_ref text, p_environment text)
 RETURNS public.capacity_test_runs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET statement_timeout TO '120s'
 SET lock_timeout TO '5s'
AS $function$
declare
  run_row public.capacity_test_runs%rowtype;
  v_piece_ids uuid[] := array[]::uuid[];
  v_operator_ids uuid[] := array[]::uuid[];
  v_machine_ids uuid[] := array[]::uuid[];
  v_session_ids uuid[] := array[]::uuid[];
  v_authorization_ids uuid[] := array[]::uuid[];
  v_machine_assignment_ids uuid[] := array[]::uuid[];
  v_cell_assignment_ids uuid[] := array[]::uuid[];
  v_lot_item_ids uuid[] := array[]::uuid[];
  v_lot_ids uuid[] := array[]::uuid[];
  v_order_ids uuid[] := array[]::uuid[];
  v_batch_ids uuid[] := array[]::uuid[];
  v_collection_event_ids uuid[] := array[]::uuid[];
  v_reading_ids uuid[] := array[]::uuid[];
  v_entry_ids uuid[] := array[]::uuid[];
begin
  if coalesce(auth.jwt() ->> 'role', '') <> 'service_role' then
    raise exception 'A limpeza transacional exige service_role.' using errcode = '42501';
  end if;

  if p_confirmation is distinct from p_test_run_id::text then
    raise exception 'A confirmação deve ser exatamente o ID completo da execução.' using errcode = '22023';
  end if;

  select * into run_row
  from public.capacity_test_runs
  where id = p_test_run_id
  for update;

  if not found then
    raise exception 'Execução de teste não localizada.' using errcode = 'P0002';
  end if;

  if run_row.is_test is distinct from true
     or run_row.project_ref = 'uozuzdfvnufsjsonswag'
     or run_row.project_ref is distinct from p_project_ref
     or run_row.environment is distinct from p_environment
     or run_row.environment not in ('development', 'staging', 'supabase_branch')
     or run_row.synthetic_prefix !~ '^ACPROD-CT-[A-Z0-9-]{8,64}$' then
    raise exception 'A execução não pertence ao ambiente isolado de teste atual.' using errcode = '42501';
  end if;

  if run_row.status not in ('draft', 'preparing', 'ready', 'completed', 'cancelled', 'failed') then
    raise exception 'Limpeza não permitida no estado %.', run_row.status using errcode = '22023';
  end if;

  -- As colunas da lease são adicionadas por migration posterior. A leitura
  -- via JSON mantém esta função instalável antes delas e passa a protegê-las
  -- assim que existirem: nunca apague dados enquanto o processo ainda estiver
  -- associado à execução sem confirmação verificável de parada.
  if (to_jsonb(run_row) ->> 'runner_instance_id') is not null
     and (to_jsonb(run_row) ->> 'runner_stopped_at') is null then
    raise exception 'Limpeza bloqueada: o runner associado ainda não confirmou a parada.' using errcode = '55006';
  end if;

  select
    coalesce(array_agg(entity_id) filter (where entity_type = 'piece'), array[]::uuid[]),
    coalesce(array_agg(entity_id) filter (where entity_type = 'operator'), array[]::uuid[]),
    coalesce(array_agg(entity_id) filter (where entity_type = 'machine'), array[]::uuid[]),
    coalesce(array_agg(entity_id) filter (where entity_type = 'operator_session'), array[]::uuid[]),
    coalesce(array_agg(entity_id) filter (where entity_type = 'workstation_authorization'), array[]::uuid[]),
    coalesce(array_agg(entity_id) filter (where entity_type = 'machine_assignment'), array[]::uuid[]),
    coalesce(array_agg(entity_id) filter (where entity_type = 'cell_assignment'), array[]::uuid[]),
    coalesce(array_agg(entity_id) filter (where entity_type = 'production_lot_item'), array[]::uuid[]),
    coalesce(array_agg(entity_id) filter (where entity_type = 'production_lot'), array[]::uuid[]),
    coalesce(array_agg(entity_id) filter (where entity_type = 'production_order'), array[]::uuid[]),
    coalesce(array_agg(entity_id) filter (where entity_type = 'import_batch'), array[]::uuid[])
  into
    v_piece_ids,
    v_operator_ids,
    v_machine_ids,
    v_session_ids,
    v_authorization_ids,
    v_machine_assignment_ids,
    v_cell_assignment_ids,
    v_lot_item_ids,
    v_lot_ids,
    v_order_ids,
    v_batch_ids
  from public.capacity_test_entities
  where test_run_id = p_test_run_id;

  -- O ledger não basta sozinho: os registros operacionais ainda existentes
  -- também precisam carregar a identidade sintética desta execução.
  if exists (
    select 1
    from public.production_pieces piece
    where piece.id = any(v_piece_ids)
      and piece.piece_uid not like run_row.synthetic_prefix || '-%'
  ) or exists (
    select 1
    from public.production_machines machine
    where machine.id = any(v_machine_ids)
      and machine.name not like run_row.synthetic_prefix || '-%'
  ) or exists (
    select 1
    from public.operators operator_row
    where operator_row.id = any(v_operator_ids)
      and operator_row.login_name not like lower(run_row.synthetic_prefix) || '-%'
  ) or exists (
    select 1
    from public.production_orders order_row
    where order_row.id = any(v_order_ids)
      and (
        order_row.order_code is null
        or order_row.order_code not like run_row.synthetic_prefix || '-%'
      )
  ) or exists (
    select 1
    from public.production_lots lot_row
    where lot_row.id = any(v_lot_ids)
      and (
        lot_row.lot_code is null
        or lot_row.lot_code not like run_row.synthetic_prefix || '-%'
      )
  ) or exists (
    select 1
    from public.production_lot_items item_row
    where item_row.id = any(v_lot_item_ids)
      and (
        item_row.item_code is null
        or item_row.item_code not like run_row.synthetic_prefix || '-%'
      )
  ) or exists (
    select 1
    from public.promob_import_batches batch_row
    where batch_row.id = any(v_batch_ids)
      and (
        batch_row.general_lot_code is null
        or batch_row.general_lot_code not like run_row.synthetic_prefix || '-%'
      )
  ) then
    raise exception 'O ledger contém entidade incompatível com o prefixo sintético da execução.' using errcode = '42501';
  end if;

  -- Ordens, lotes, itens e batches só podem ser removidos quando não forem
  -- compartilhados com peças fora do ledger confirmado.
  if exists (
    select 1
    from public.production_pieces piece
    where not exists (
        select 1
        from public.capacity_test_entities ledger_piece
        where ledger_piece.test_run_id = p_test_run_id
          and ledger_piece.entity_type = 'piece'
          and ledger_piece.entity_id = piece.id
      )
      and (
        piece.production_order_id = any(v_order_ids)
        or piece.lot_id = any(v_lot_ids)
        or piece.legacy_production_lot_item_id = any(v_lot_item_ids)
        or piece.pcp_import_batch_id = any(v_batch_ids)
      )
  ) then
    raise exception 'Entidades do cenário estão compartilhadas com peças fora da execução.' using errcode = '23503';
  end if;

  -- A hierarquia estrutural precisa estar integralmente no ledger. Uma ordem
  -- sintética jamais pode levar junto um lote não registrado, e um lote
  -- sintético jamais pode levar junto um item não registrado.
  if exists (
    select 1
    from public.production_lots lot_row
    where (
        lot_row.order_id = any(v_order_ids)
        or lot_row.production_order_id = any(v_order_ids)
      )
      and not exists (
        select 1
        from public.capacity_test_entities owned_lot
        where owned_lot.test_run_id = p_test_run_id
          and owned_lot.entity_type = 'production_lot'
          and owned_lot.entity_id = lot_row.id
      )
  ) or exists (
    select 1
    from public.production_lots lot_row
    where lot_row.id = any(v_lot_ids)
      and (
        lot_row.order_id <> all(v_order_ids)
        or (
          lot_row.production_order_id is not null
          and lot_row.production_order_id <> all(v_order_ids)
        )
      )
  ) or exists (
    select 1
    from public.production_lot_items item_row
    where item_row.lot_id = any(v_lot_ids)
      and not exists (
        select 1
        from public.capacity_test_entities owned_item
        where owned_item.test_run_id = p_test_run_id
          and owned_item.entity_type = 'production_lot_item'
          and owned_item.entity_id = item_row.id
      )
  ) or exists (
    select 1
    from public.production_lot_items item_row
    where item_row.id = any(v_lot_item_ids)
      and item_row.lot_id <> all(v_lot_ids)
  ) then
    raise exception 'A hierarquia estrutural da execução contém filho não registrado ou referência externa.' using errcode = '23503';
  end if;

  -- Rotas e tags são geradas pelo importador e pertencem transitivamente aos
  -- lotes, itens e peças do ledger. Elas só são aceitas quando todas as suas
  -- referências continuam internas e a identificação mantém o prefixo.
  if exists (
    select 1
    from public.production_routes route_row
    where route_row.lot_id = any(v_lot_ids)
      and route_row.order_item_id is not null
  ) or exists (
    select 1
    from public.production_tags tag_row
    where (
        tag_row.lot_id = any(v_lot_ids)
        or tag_row.item_id = any(v_lot_item_ids)
        or tag_row.piece_id = any(v_piece_ids)
      )
      and (
        tag_row.tag_value not like run_row.synthetic_prefix || '-%'
        or tag_row.lot_id <> all(v_lot_ids)
        or (
          tag_row.item_id is not null
          and tag_row.item_id <> all(v_lot_item_ids)
        )
        or (
          tag_row.piece_id is not null
          and tag_row.piece_id <> all(v_piece_ids)
        )
      )
  ) then
    raise exception 'Rota ou tag derivada contém referência fora do cenário sintético.' using errcode = '23503';
  end if;

  -- Estas estruturas poderiam desaparecer antes das guardas dos pais por
  -- também possuírem CASCADE para peça. Como não fazem parte do cenário de
  -- capacidade, sua presença bloqueia a limpeza antes da primeira exclusão.
  if exists (
    select 1
    from public.replacement_orders replacement_row
    where replacement_row.original_piece_id = any(v_piece_ids)
       or replacement_row.replacement_piece_id = any(v_piece_ids)
       or replacement_row.lot_id = any(v_lot_ids)
       or replacement_row.production_order_id = any(v_order_ids)
  ) or exists (
    select 1
    from public.rework_orders rework_row
    where rework_row.original_piece_id = any(v_piece_ids)
       or rework_row.replacement_piece_id = any(v_piece_ids)
  ) or exists (
    select 1
    from public.packing_volume_items packed_item
    where packed_item.piece_id = any(v_piece_ids)
  ) then
    raise exception 'A execução possui estrutura produtiva inesperada não registrada no ledger.' using errcode = '23503';
  end if;

  -- Capas são derivadas do batch, mas não podem ser compartilhadas com
  -- volumes, remessas ou lotes externos ao ledger confirmado.
  if exists (
    select 1
    from public.customer_covers cover_row
    where cover_row.pcp_import_batch_id = any(v_batch_ids)
      and cover_row.general_lot_code not like run_row.synthetic_prefix || '-%'
  ) or exists (
    select 1
    from public.production_lots lot_row
    join public.customer_covers cover_row on cover_row.id = lot_row.customer_cover_id
    where cover_row.pcp_import_batch_id = any(v_batch_ids)
      and not exists (
        select 1
        from public.capacity_test_entities owned_lot
        where owned_lot.test_run_id = p_test_run_id
          and owned_lot.entity_type = 'production_lot'
          and owned_lot.entity_id = lot_row.id
      )
  ) or exists (
    select 1
    from public.packing_volumes volume_row
    join public.customer_covers cover_row on cover_row.id = volume_row.customer_cover_id
    where cover_row.pcp_import_batch_id = any(v_batch_ids)
  ) or exists (
    select 1
    from public.shipments shipment_row
    join public.customer_covers cover_row on cover_row.id = shipment_row.customer_cover_id
    where cover_row.pcp_import_batch_id = any(v_batch_ids)
  ) then
    raise exception 'Capa derivada do batch está compartilhada com estrutura externa.' using errcode = '23503';
  end if;

  -- Dependências são derivadas apenas de FKs para as entidades confirmadas no
  -- ledger. O payload recebido da coleta nunca amplia o escopo da limpeza.
  select coalesce(array_agg(id), array[]::uuid[])
  into v_collection_event_ids
  from public.production_collection_events
  where piece_id = any(v_piece_ids)
     or lot_id = any(v_lot_ids)
     or production_order_id = any(v_order_ids)
     or pcp_import_batch_id = any(v_batch_ids);

  select coalesce(array_agg(id), array[]::uuid[])
  into v_reading_ids
  from public.production_stage_readings
  where piece_id = any(v_piece_ids)
     or item_id = any(v_lot_item_ids)
     or lot_id = any(v_lot_ids)
     or production_order_id = any(v_order_ids);

  select coalesce(array_agg(id), array[]::uuid[])
  into v_entry_ids
  from public.production_entries
  where lot_id = any(v_lot_ids)
     or production_order_id = any(v_order_ids)
     or order_id = any(v_order_ids)
     or pcp_import_batch_id = any(v_batch_ids);

  delete from public.quality_nonconformities
  where piece_id = any(v_piece_ids)
     or lot_id = any(v_lot_ids)
     or production_order_id = any(v_order_ids);
  delete from public.occurrences
  where lot_id = any(v_lot_ids)
     or order_id = any(v_order_ids)
     or production_order_id = any(v_order_ids);
  delete from public.production_events
  where piece_id = any(v_piece_ids)
     or lot_id = any(v_lot_ids)
     or production_order_id = any(v_order_ids);
  delete from public.production_collection_events where id = any(v_collection_event_ids);
  delete from public.production_stage_readings where id = any(v_reading_ids);
  delete from public.manual_production_records
  where pcp_import_batch_id = any(v_batch_ids)
     or production_entry_id = any(v_entry_ids);
  delete from public.production_entries where id = any(v_entry_ids);
  -- Estes contadores são projeções derivadas. Removê-los pelos lotes exatos do
  -- ledger evita colisões de unicidade no ON DELETE SET NULL das máquinas.
  delete from public.production_realtime_counters where lot_id = any(v_lot_ids);

  -- A exclusão histórica também abrangia sessões ligadas aos operadores do
  -- cenário. Materialize exatamente esse conjunto para que a guarda cubra
  -- todas as linhas que o DELETE removerá, não apenas as entradas do ledger.
  select coalesce(array_agg(id), array[]::uuid[])
  into v_session_ids
  from public.operator_sessions
  where id = any(v_session_ids)
     or operator_id = any(v_operator_ids);

  perform public.capacity_test_assert_no_fk_references(
    'public.operator_sessions'::regclass,
    v_session_ids
  );
  delete from public.operator_sessions where id = any(v_session_ids);

  perform public.capacity_test_assert_no_fk_references(
    'public.workstation_operator_authorizations'::regclass,
    v_authorization_ids
  );
  delete from public.workstation_operator_authorizations where id = any(v_authorization_ids);

  perform public.capacity_test_assert_no_fk_references(
    'public.operator_machine_assignments'::regclass,
    v_machine_assignment_ids
  );
  delete from public.operator_machine_assignments where id = any(v_machine_assignment_ids);

  perform public.capacity_test_assert_no_fk_references(
    'public.operator_cell_assignments'::regclass,
    v_cell_assignment_ids
  );
  delete from public.operator_cell_assignments where id = any(v_cell_assignment_ids);

  perform public.capacity_test_assert_no_fk_references(
    'public.operators'::regclass,
    v_operator_ids
  );
  delete from public.operators where id = any(v_operator_ids);

  perform public.capacity_test_assert_no_fk_references(
    'public.production_machines'::regclass,
    v_machine_ids
  );
  delete from public.production_machines where id = any(v_machine_ids);
  delete from public.production_tags
  where lot_id = any(v_lot_ids)
     or item_id = any(v_lot_item_ids)
     or piece_id = any(v_piece_ids);
  delete from public.production_routes where lot_id = any(v_lot_ids);
  delete from public.lot_step_events where lot_id = any(v_lot_ids);
  delete from public.promob_import_differences where import_batch_id = any(v_batch_ids);
  delete from public.pcp_import_logs where import_file_id = any(v_batch_ids);
  delete from public.pcp_import_rows where batch_id = any(v_batch_ids);
  delete from public.customer_covers where pcp_import_batch_id = any(v_batch_ids);
  delete from public.production_search_index
  where entity_type = 'production_order'
    and entity_id = any(v_order_ids);

  perform public.capacity_test_assert_no_fk_references(
    'public.production_pieces'::regclass,
    v_piece_ids
  );
  delete from public.production_pieces where id = any(v_piece_ids);

  perform public.capacity_test_assert_no_fk_references(
    'public.production_lot_items'::regclass,
    v_lot_item_ids
  );
  delete from public.production_lot_items where id = any(v_lot_item_ids);

  perform public.capacity_test_assert_no_fk_references(
    'public.production_lots'::regclass,
    v_lot_ids
  );
  delete from public.production_lots where id = any(v_lot_ids);

  perform public.capacity_test_assert_no_fk_references(
    'public.promob_import_batches'::regclass,
    v_batch_ids
  );
  delete from public.promob_import_batches where id = any(v_batch_ids);

  perform public.capacity_test_assert_no_fk_references(
    'public.production_orders'::regclass,
    v_order_ids
  );
  delete from public.production_orders where id = any(v_order_ids);

  update public.capacity_test_runs
  set status = 'cleaned',
      cleaned_at = clock_timestamp(),
      updated_at = clock_timestamp(),
      state_version = state_version + 1
  where id = p_test_run_id
  returning * into run_row;

  return run_row;
end;
$function$

CREATE OR REPLACE FUNCTION public.capacity_test_create_scenario(p_test_run_id uuid, p_requested_by uuid, p_project_ref text, p_environment text, p_scenario_items jsonb)
 RETURNS public.capacity_test_runs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
 SET lock_timeout TO '5s'
AS $function$
declare
  run_row public.capacity_test_runs%rowtype;
  scenario_item jsonb;
  v_item_count integer;
  v_cut_count integer;
  v_edge_count integer;
  v_cnc_count integer;
  v_separation_count integer;
  v_cut_items integer;
  v_edge_items integer;
  v_cnc_items integer;
  v_separation_items integer;
  v_distinct_machines integer;
  v_distinct_operators integer;
  v_distinct_registrations integer;
  v_distinct_agents integer;
  v_stage_key text;
  v_stage_label text;
  v_machine_prefix text;
  v_machine_name text;
  v_cell_id uuid;
  v_cell_name text;
  v_stored_cell_name text;
  v_station_name text;
  v_operator_name text;
  v_registration text;
  v_login_name text;
  v_agent_key text;
  v_machine_id uuid;
  v_operator_id uuid;
  v_cell_assignment_id uuid;
  v_machine_assignment_id uuid;
  v_authorization_id uuid;
begin
  if coalesce(auth.jwt() ->> 'role', '') <> 'service_role' then
    raise exception 'A criação transacional do cenário exige service_role.' using errcode = '42501';
  end if;

  if p_test_run_id is null
     or p_requested_by is null
     or nullif(btrim(p_project_ref), '') is null
     or p_environment not in ('development', 'staging', 'supabase_branch')
     or p_project_ref = 'uozuzdfvnufsjsonswag' then
    raise exception 'Contexto isolado do cenário é inválido.' using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.profiles profile_row
    where profile_row.id = p_requested_by
      and profile_row.role = 'admin'
      and profile_row.active is true
  ) then
    raise exception 'Administrador ativo não localizado para a criação do cenário.' using errcode = '42501';
  end if;

  select * into run_row
  from public.capacity_test_runs
  where id = p_test_run_id
  for update;

  if not found then
    raise exception 'Execução de teste não localizada.' using errcode = 'P0002';
  end if;

  if run_row.is_test is distinct from true
     or run_row.project_ref = 'uozuzdfvnufsjsonswag'
     or run_row.project_ref is distinct from p_project_ref
     or run_row.environment is distinct from p_environment
     or run_row.synthetic_prefix !~ '^ACPROD-CT-[A-Z0-9-]{8,64}$' then
    raise exception 'A execução não pertence ao ambiente isolado de teste atual.' using errcode = '42501';
  end if;

  if run_row.status not in ('draft', 'preparing', 'failed') then
    raise exception 'Cenário não pode ser preparado no estado %.', run_row.status using errcode = '22023';
  end if;

  if run_row.runner_instance_id is not null and run_row.runner_stopped_at is null then
    raise exception 'Cenário não pode ser recriado enquanto houver runner ativo.' using errcode = '55006';
  end if;

  if exists (
    select 1 from public.capacity_test_entities entity_row
    where entity_row.test_run_id = p_test_run_id
  ) or exists (
    select 1 from public.capacity_test_agents agent_row
    where agent_row.test_run_id = p_test_run_id
  ) then
    raise exception 'Esta execução já possui cenário sintético registrado.' using errcode = '55000';
  end if;

  begin
    v_cut_count := coalesce((run_row.configuration ->> 'cut_machines')::integer, 25);
    v_edge_count := coalesce((run_row.configuration ->> 'edge_machines')::integer, 50);
    v_cnc_count := coalesce((run_row.configuration ->> 'cnc_machines')::integer, 6);
    v_separation_count := coalesce((run_row.configuration ->> 'separation_stations')::integer, 2);
  exception
    when invalid_text_representation or numeric_value_out_of_range then
      raise exception 'Configuração de máquinas inválida.' using errcode = '22023';
  end;

  if v_cut_count not between 1 and 250
     or v_edge_count not between 1 and 500
     or v_cnc_count not between 1 and 100
     or v_separation_count not between 1 and 50 then
    raise exception 'Configuração de máquinas fora dos limites permitidos.' using errcode = '22023';
  end if;

  if jsonb_typeof(p_scenario_items) is distinct from 'array' then
    raise exception 'Itens do cenário devem formar um array JSON.' using errcode = '22023';
  end if;

  v_item_count := jsonb_array_length(p_scenario_items);
  if v_item_count <> v_cut_count + v_edge_count + v_cnc_count + v_separation_count then
    raise exception 'Quantidade de itens do cenário diverge da configuração da execução.' using errcode = '22023';
  end if;

  select
    count(*) filter (where item ->> 'stage_key' = 'cut'),
    count(*) filter (where item ->> 'stage_key' = 'edge'),
    count(*) filter (where item ->> 'stage_key' = 'cnc'),
    count(*) filter (where item ->> 'stage_key' = 'separation'),
    count(distinct item ->> 'machine_name'),
    count(distinct lower(item ->> 'login_name')),
    count(distinct item ->> 'registration'),
    count(distinct item ->> 'agent_key')
  into
    v_cut_items,
    v_edge_items,
    v_cnc_items,
    v_separation_items,
    v_distinct_machines,
    v_distinct_operators,
    v_distinct_registrations,
    v_distinct_agents
  from jsonb_array_elements(p_scenario_items) as input_rows(item);

  if v_cut_items <> v_cut_count
     or v_edge_items <> v_edge_count
     or v_cnc_items <> v_cnc_count
     or v_separation_items <> v_separation_count
     or v_distinct_machines <> v_item_count
     or v_distinct_operators <> v_item_count
     or v_distinct_registrations <> v_item_count
     or v_distinct_agents <> v_item_count then
    raise exception 'Itens do cenário possuem etapa, identificador ou credencial duplicada/inválida.' using errcode = '22023';
  end if;

  for scenario_item in
    select item
    from jsonb_array_elements(p_scenario_items) with ordinality as input_rows(item, ordinal)
    order by ordinal
  loop
    if jsonb_typeof(scenario_item) <> 'object' then
      raise exception 'Item do cenário possui formato inválido.' using errcode = '22023';
    end if;

    v_stage_key := scenario_item ->> 'stage_key';
    v_stage_label := scenario_item ->> 'stage_label';
    v_machine_name := scenario_item ->> 'machine_name';
    v_station_name := scenario_item ->> 'station_name';
    v_operator_name := scenario_item ->> 'operator_name';
    v_registration := scenario_item ->> 'registration';
    v_login_name := scenario_item ->> 'login_name';
    v_agent_key := scenario_item ->> 'agent_key';

    begin
      v_cell_id := (scenario_item ->> 'cell_id')::uuid;
    exception when invalid_text_representation then
      raise exception 'Célula inválida em item do cenário.' using errcode = '22023';
    end;
    v_cell_name := scenario_item ->> 'cell_name';

    v_stage_label := case v_stage_key
      when 'cut' then 'Corte'
      when 'edge' then 'Borda'
      when 'cnc' then 'Usinagem'
      when 'separation' then 'Separação'
    end;
    v_machine_prefix := case v_stage_key
      when 'cut' then 'CORTE'
      when 'edge' then 'COLADEIRA'
      when 'cnc' then 'USINAGEM'
      when 'separation' then 'SEPARACAO'
    end;

    if v_stage_label is null
       or scenario_item ->> 'stage_label' is distinct from v_stage_label
       or nullif(btrim(v_machine_name), '') is null
       or v_machine_name not like run_row.synthetic_prefix || '-' || v_machine_prefix || '-%'
       or nullif(btrim(v_station_name), '') is null
       or v_station_name not like v_stage_label || ' %'
       or nullif(btrim(v_operator_name), '') is null
       or v_operator_name not like run_row.synthetic_prefix || ' OPERADOR %'
       or nullif(btrim(v_login_name), '') is null
       or v_login_name not like lower(run_row.synthetic_prefix) || '-op-%'
       or nullif(btrim(v_agent_key), '') is null
       or v_agent_key not like run_row.synthetic_prefix || '-AGENT-%'
       or nullif(btrim(v_registration), '') is null
       or v_registration !~ '^[A-Z0-9]{12,32}$'
       or v_registration not like left(replace(run_row.synthetic_prefix, '-', ''), 24) || '%' then
      raise exception 'Identidade sintética inválida em item do cenário.' using errcode = '22023';
    end if;

    select cell_row.name into v_stored_cell_name
    from public.cells cell_row
    where cell_row.id = v_cell_id
      and cell_row.active is true;

    if not found
       or v_stored_cell_name is distinct from v_cell_name
       or (v_stage_key = 'cut' and lower(v_stored_cell_name) <> 'corte')
       or (v_stage_key = 'edge' and lower(v_stored_cell_name) <> 'borda')
       or (v_stage_key = 'cnc' and lower(v_stored_cell_name) not in ('usinagem', 'usinagem cnc'))
       or (v_stage_key = 'separation' and lower(v_stored_cell_name) not in ('separação', 'separacao')) then
      raise exception 'Célula do item não corresponde à etapa sintética.' using errcode = '23503';
    end if;

    insert into public.production_machines (
      name, cell_name, station_name, metric_unit, active, description,
      allows_normal_production, allows_replacement, allows_rework
    ) values (
      v_machine_name, v_cell_name, v_station_name, 'pieces', true,
      'Registro sintético exclusivo do teste ' || run_row.id::text,
      true, false, false
    ) returning id into v_machine_id;

    insert into public.capacity_test_entities (
      test_run_id, entity_type, entity_id, synthetic_key, stage
    ) values (
      run_row.id, 'machine', v_machine_id, v_machine_name, v_stage_key
    );

    insert into public.operators (
      name, role, active, created_by, registration, login_name,
      primary_cell, cells, shift, login_enabled,
      primary_cell_id, primary_machine_id
    ) values (
      v_operator_name, 'operator', true, p_requested_by, v_registration, v_login_name,
      v_cell_name, array[v_cell_name], '1', true,
      v_cell_id, v_machine_id
    ) returning id into v_operator_id;

    insert into public.capacity_test_entities (
      test_run_id, entity_type, entity_id, synthetic_key, metadata
    ) values (
      run_row.id, 'operator', v_operator_id, v_login_name,
      jsonb_build_object('machine_id', v_machine_id)
    );

    insert into public.operator_cell_assignments (
      operator_id, cell_id, is_primary, active, assigned_by
    ) values (
      v_operator_id, v_cell_id, true, true, p_requested_by
    ) returning id into v_cell_assignment_id;

    insert into public.capacity_test_entities (
      test_run_id, entity_type, entity_id, synthetic_key
    ) values (
      run_row.id, 'cell_assignment', v_cell_assignment_id, v_cell_assignment_id::text
    );

    insert into public.operator_machine_assignments (
      operator_id, machine_id, is_primary, active, assigned_by
    ) values (
      v_operator_id, v_machine_id, true, true, p_requested_by
    ) returning id into v_machine_assignment_id;

    insert into public.capacity_test_entities (
      test_run_id, entity_type, entity_id, synthetic_key
    ) values (
      run_row.id, 'machine_assignment', v_machine_assignment_id, v_machine_assignment_id::text
    );

    insert into public.workstation_operator_authorizations (
      operator_id, machine_id, cell_id, shift, authorization_type,
      is_active, authorized_by, training_validated, notes
    ) values (
      v_operator_id, v_machine_id, v_cell_id, '1', 'temporary',
      true, p_requested_by, true,
      'Autorização sintética do teste ' || run_row.id::text
    ) returning id into v_authorization_id;

    insert into public.capacity_test_entities (
      test_run_id, entity_type, entity_id, synthetic_key
    ) values (
      run_row.id, 'workstation_authorization', v_authorization_id, v_authorization_id::text
    );

    insert into public.capacity_test_agents (
      test_run_id, agent_key, stage, machine_id, operator_id, metadata
    ) values (
      run_row.id, v_agent_key, v_stage_label, v_machine_id, v_operator_id,
      jsonb_build_object('login_name', v_login_name)
    );
  end loop;

  update public.capacity_test_runs
  set status = 'preparing',
      preflight = jsonb_build_object(
        'passed', false,
        'file_valid', false,
        'imported_piece_count', 0,
        'expected_piece_count', run_row.total_pieces,
        'machines_created', v_item_count,
        'operators_created', v_item_count,
        'assignments_created', v_item_count * 3,
        'scenario_identified', true,
        'environment_allowed', true,
        'checked_at', clock_timestamp()
      ),
      state_version = state_version + 1,
      updated_at = clock_timestamp()
  where id = run_row.id
  returning * into run_row;

  return run_row;
end;
$function$

CREATE OR REPLACE FUNCTION public.capacity_test_enforce_prefix_free()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_new_scope text;
  v_old_scope text;
  v_lock_key bigint;
begin
  -- Execuções limpas permanecem somente para auditoria e não reservam mais
  -- namespace. Isso também mantém compatibilidade com conflitos históricos.
  if new.status is not distinct from 'cleaned' then
    return new;
  end if;

  if new.id is null
     or new.project_ref is null
     or btrim(new.project_ref) = ''
     or new.environment is null
     or btrim(new.environment) = ''
     or new.synthetic_prefix is null
     or new.synthetic_prefix !~ '^ACPROD-CT-[A-Z0-9-]{8,64}$' then
    raise exception 'Namespace sintético inválido para a execução de capacidade.' using errcode = '23514';
  end if;

  v_new_scope := new.project_ref || chr(31) || new.environment;
  if tg_op = 'UPDATE' then
    v_old_scope := old.project_ref || chr(31) || old.environment;
  end if;

  -- Duas atualizações que troquem de ambiente adquirem ambas as travas na
  -- mesma ordem numérica, evitando deadlock e janela de dupla reserva.
  for v_lock_key in
    select distinct pg_catalog.hashtextextended(scope_value, 0)
    from pg_catalog.unnest(array[v_new_scope, v_old_scope]) as scopes(scope_value)
    where scope_value is not null
    order by 1
  loop
    perform pg_catalog.pg_advisory_xact_lock(v_lock_key);
  end loop;

  if exists (
    select 1
    from public.capacity_test_runs existing_run
    where existing_run.project_ref = new.project_ref
      and existing_run.environment = new.environment
      and existing_run.id <> new.id
      and existing_run.status is distinct from 'cleaned'
      and (
        existing_run.synthetic_prefix = new.synthetic_prefix
        or left(existing_run.synthetic_prefix, char_length(new.synthetic_prefix) + 1)
          = new.synthetic_prefix || '-'
        or left(new.synthetic_prefix, char_length(existing_run.synthetic_prefix) + 1)
          = existing_run.synthetic_prefix || '-'
      )
  ) then
    raise exception 'Prefixo sintético igual, ancestral ou descendente já reservado neste ambiente.' using errcode = '23505';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.capacity_test_enforce_runner_lease()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if new.status = 'ready' and old.status is distinct from new.status then
    new.runner_instance_id := null;
    new.runner_stop_token_hash := null;
    new.runner_claimed_at := null;
    new.runner_stopped_at := null;
  end if;

  if new.status = 'running' and old.status is distinct from new.status then
    if new.runner_instance_id is null
       or new.runner_stop_token_hash is null
       or new.runner_claimed_at is null
       or new.runner_stopped_at is not null then
      raise exception 'Execução sem lease ativa e verificável do runner.' using errcode = '55000';
    end if;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.capacity_test_record_sample(p_test_run_id uuid, p_sample jsonb)
 RETURNS public.capacity_test_runs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  run_row public.capacity_test_runs%rowtype;
  sent_delta bigint := greatest(coalesce((p_sample ->> 'sent')::bigint, 0), 0);
  received_delta bigint := greatest(coalesce((p_sample ->> 'received')::bigint, 0), 0);
  processed_delta bigint := greatest(coalesce((p_sample ->> 'processed')::bigint, 0), 0);
  success_delta bigint := greatest(coalesce((p_sample ->> 'success')::bigint, 0), 0);
  error_delta bigint := greatest(coalesce((p_sample ->> 'errors')::bigint, 0), 0);
  duplicate_delta bigint := greatest(coalesce((p_sample ->> 'duplicates')::bigint, 0), 0);
  lost_delta bigint := greatest(coalesce((p_sample ->> 'lost')::bigint, 0), 0);
begin
  if not public.capacity_test_is_admin() then
    raise exception 'Apenas administradores ativos podem registrar métricas de capacidade.' using errcode = '42501';
  end if;

  select * into run_row from public.capacity_test_runs where id = p_test_run_id for update;
  if not found then raise exception 'Execução de teste não localizada.' using errcode = 'P0002'; end if;
  if run_row.status not in ('running', 'paused', 'cancelling') then
    raise exception 'Métricas não são aceitas no estado %.', run_row.status using errcode = '22023';
  end if;

  insert into public.capacity_test_metric_samples (
    test_run_id, stage, machine_id, operator_id, sent, received, processed,
    success, errors, duplicates, queue_depth, throughput_per_second,
    latency_avg_ms, latency_p50_ms, latency_p90_ms, latency_p95_ms,
    latency_p99_ms, latency_max_ms, realtime_delay_ms, metadata
  ) values (
    p_test_run_id,
    nullif(p_sample ->> 'stage', ''),
    nullif(p_sample ->> 'machine_id', '')::uuid,
    nullif(p_sample ->> 'operator_id', '')::uuid,
    sent_delta, received_delta, processed_delta, success_delta, error_delta, duplicate_delta,
    greatest(coalesce((p_sample ->> 'queue_depth')::integer, 0), 0),
    greatest(coalesce((p_sample ->> 'throughput_per_second')::numeric, 0), 0),
    nullif(p_sample ->> 'latency_avg_ms', '')::numeric,
    nullif(p_sample ->> 'latency_p50_ms', '')::numeric,
    nullif(p_sample ->> 'latency_p90_ms', '')::numeric,
    nullif(p_sample ->> 'latency_p95_ms', '')::numeric,
    nullif(p_sample ->> 'latency_p99_ms', '')::numeric,
    nullif(p_sample ->> 'latency_max_ms', '')::numeric,
    nullif(p_sample ->> 'realtime_delay_ms', '')::numeric,
    coalesce(p_sample -> 'metadata', '{}'::jsonb)
  );

  update public.capacity_test_runs
  set total_sent = total_sent + sent_delta,
      total_received = total_received + received_delta,
      total_processed = total_processed + processed_delta,
      total_success = total_success + success_delta,
      total_errors = total_errors + error_delta,
      total_duplicates = total_duplicates + duplicate_delta,
      total_lost = total_lost + lost_delta,
      current_rate = greatest(coalesce((p_sample ->> 'throughput_per_second')::numeric, 0), 0),
      peak_rate = greatest(peak_rate, greatest(coalesce((p_sample ->> 'throughput_per_second')::numeric, 0), 0)),
      average_latency_ms = coalesce(nullif(p_sample ->> 'latency_avg_ms', '')::numeric, average_latency_ms),
      p50_latency_ms = coalesce(nullif(p_sample ->> 'latency_p50_ms', '')::numeric, p50_latency_ms),
      p95_latency_ms = coalesce(nullif(p_sample ->> 'latency_p95_ms', '')::numeric, p95_latency_ms),
      p99_latency_ms = coalesce(nullif(p_sample ->> 'latency_p99_ms', '')::numeric, p99_latency_ms),
      updated_at = now()
  where id = p_test_run_id
  returning * into run_row;

  return run_row;
end;
$function$

CREATE OR REPLACE FUNCTION public.collect_replacement_stage_v2(p_session_token text, p_barcode text, p_client_event_id uuid, p_device_id text, p_created_at_client timestamp with time zone, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
declare
  v_auth_user_id uuid := auth.uid();
  v_now timestamptz := clock_timestamp();
  v_code text := btrim(coalesce(p_barcode, ''));
  v_device_id text := btrim(coalesce(p_device_id, ''));
  v_session public.operator_sessions%rowtype;
  v_operator public.operators%rowtype;
  v_cell public.cells%rowtype;
  v_machine public.production_machines%rowtype;
  v_order public.replacement_orders%rowtype;
  v_replacement_piece public.production_pieces%rowtype;
  v_original_piece public.production_pieces%rowtype;
  v_route text[];
  v_completed text[];
  v_expected_code text;
  v_expected_label text;
  v_current_code text;
  v_next_code text;
  v_next_label text;
  v_current_position integer;
  v_expected_position integer;
  v_is_last boolean := false;
  v_reading_id uuid;
  v_existing_result jsonb;
  v_result jsonb;
  v_lot_result jsonb;
  v_next_cell_id uuid;
  v_offline_reconciliation boolean := coalesce((p_payload ->> 'queued_offline')::boolean, false);
begin
  if v_auth_user_id is null then
    return jsonb_build_object('success', false, 'result_status', 'blocked', 'reason_code', 'AUTH_REQUIRED', 'message', 'Autenticacao do sistema expirada.');
  end if;
  if v_code = '' then
    return jsonb_build_object('success', false, 'result_status', 'blocked', 'reason_code', 'EMPTY_BARCODE', 'message', 'Codigo de barras nao informado.');
  end if;
  if p_client_event_id is null then
    return jsonb_build_object('success', false, 'result_status', 'blocked', 'reason_code', 'CLIENT_EVENT_REQUIRED', 'message', 'Identificador idempotente da leitura nao informado.');
  end if;
  if v_device_id = '' then
    return jsonb_build_object('success', false, 'result_status', 'blocked', 'reason_code', 'DEVICE_REQUIRED', 'message', 'Dispositivo do posto nao identificado.');
  end if;

  select event.result_payload into v_existing_result
  from public.production_collection_events event
  where event.client_event_id = p_client_event_id::text;
  if v_existing_result is not null then
    return v_existing_result || jsonb_build_object('idempotent', true);
  end if;

  select * into v_session
  from public.operator_sessions session_row
  where session_row.token_hash = encode(extensions.digest(coalesce(p_session_token, ''), 'sha256'), 'hex')
    and session_row.auth_user_id = v_auth_user_id
  for update;

  if v_session.id is null then
    return jsonb_build_object('success', false, 'result_status', 'blocked', 'reason_code', 'SESSION_INVALID', 'message', 'Sessao operacional nao localizada para este usuario.');
  end if;
  if v_session.revoked_at is not null then
    return jsonb_build_object('success', false, 'result_status', 'blocked', 'reason_code', 'SESSION_REVOKED', 'message', 'Sessao operacional revogada. Realize novo login.');
  end if;
  if v_session.ended_at is not null then
    return jsonb_build_object('success', false, 'result_status', 'blocked', 'reason_code', 'SESSION_ENDED', 'message', 'Sessao operacional encerrada. Realize novo login.');
  end if;
  if v_session.device_id is distinct from v_device_id then
    return jsonb_build_object('success', false, 'result_status', 'blocked', 'reason_code', 'DEVICE_MISMATCH', 'message', 'A sessao pertence a outro dispositivo.');
  end if;
  if v_session.expires_at <= v_now and not (
    v_offline_reconciliation
    and p_created_at_client is not null
    and p_created_at_client <= v_session.expires_at
    and v_now <= coalesce(v_session.sync_grace_until, v_session.expires_at + interval '24 hours')
  ) then
    return jsonb_build_object('success', false, 'result_status', 'blocked', 'reason_code', 'SESSION_EXPIRED', 'message', 'Sessao operacional expirada. Realize novo login.');
  end if;
  if v_session.cell_id is null then
    return jsonb_build_object('success', false, 'result_status', 'blocked', 'reason_code', 'CONTEXT_REQUIRED', 'message', 'Selecione a celula e o posto antes de bipar.');
  end if;

  select * into v_operator from public.operators where id = v_session.operator_id;
  if v_operator.id is null or v_operator.active is not true or coalesce(v_operator.login_enabled, true) is not true then
    return jsonb_build_object('success', false, 'result_status', 'blocked', 'reason_code', 'OPERATOR_INACTIVE', 'message', 'Operador inativo ou sem acesso a coleta.');
  end if;

  select * into v_cell from public.cells where id = v_session.cell_id and active = true;
  if v_cell.id is null then
    return jsonb_build_object('success', false, 'result_status', 'blocked', 'reason_code', 'WRONG_CELL', 'message', 'Celula da sessao inativa ou inexistente.');
  end if;

  if not exists (
    select 1 from public.operator_cell_assignments assignment
    where assignment.operator_id = v_operator.id
      and assignment.cell_id = v_cell.id
      and assignment.active = true
      and assignment.valid_from <= v_now
      and (assignment.valid_until is null or assignment.valid_until > v_now)
  ) then
    return jsonb_build_object('success', false, 'result_status', 'blocked', 'reason_code', 'OPERATOR_UNAUTHORIZED', 'message', 'Operador nao autorizado para esta celula.');
  end if;

  if v_session.machine_id is not null then
    select * into v_machine from public.production_machines where id = v_session.machine_id;
    if v_machine.id is null
       or v_machine.active is not true
       or v_machine.allows_replacement is not true then
      return jsonb_build_object('success', false, 'result_status', 'blocked', 'reason_code', 'MACHINE_INACTIVE', 'message', 'Maquina inativa ou nao habilitada para reposicao.');
    end if;
    if lower(btrim(v_machine.cell_name)) <> lower(btrim(v_cell.name)) then
      return jsonb_build_object('success', false, 'result_status', 'blocked', 'reason_code', 'WRONG_MACHINE', 'message', 'Maquina nao pertence a celula da sessao.');
    end if;
    if exists (
      select 1 from public.operator_machine_assignments assignment
      where assignment.operator_id = v_operator.id
        and assignment.active = true
        and assignment.valid_from <= v_now
        and (assignment.valid_until is null or assignment.valid_until > v_now)
    ) and not exists (
      select 1 from public.operator_machine_assignments assignment
      where assignment.operator_id = v_operator.id
        and assignment.machine_id = v_machine.id
        and assignment.active = true
        and assignment.valid_from <= v_now
        and (assignment.valid_until is null or assignment.valid_until > v_now)
    ) then
      return jsonb_build_object('success', false, 'result_status', 'blocked', 'reason_code', 'OPERATOR_UNAUTHORIZED', 'message', 'Operador nao autorizado para esta maquina.');
    end if;
  end if;

  if exists (
    select 1 from public.workstation_operator_authorizations authz
    where authz.is_active = true
      and authz.training_validated = true
      and authz.valid_from <= v_now
      and (authz.valid_until is null or authz.valid_until > v_now)
      and (authz.cell_id = v_cell.id or authz.machine_id = v_session.machine_id)
  ) and not exists (
    select 1 from public.workstation_operator_authorizations authz
    where authz.operator_id = v_operator.id
      and authz.is_active = true
      and authz.training_validated = true
      and authz.valid_from <= v_now
      and (authz.valid_until is null or authz.valid_until > v_now)
      and (authz.cell_id = v_cell.id or authz.machine_id = v_session.machine_id)
      and (authz.shift is null or authz.shift = v_session.shift_snapshot)
  ) then
    return jsonb_build_object('success', false, 'result_status', 'blocked', 'reason_code', 'OPERATOR_UNAUTHORIZED', 'message', 'Operador sem autorizacao vigente para o posto.');
  end if;

  select replacement.* into v_order
  from public.replacement_orders replacement
  join public.production_pieces piece on piece.id = replacement.replacement_piece_id
  where replacement.replacement_piece_id is not null
    and (
      replacement.replacement_barcode = v_code
      or replacement.replacement_code = v_code
      or piece.piece_uid = v_code
      or piece.traceability_code = v_code
      or piece.piece_code = v_code
      or piece.id::text = v_code
    )
  order by case when replacement.status in ('released', 'in_production') then 0 else 1 end,
           replacement.created_at desc
  limit 1;

  if v_order.id is null then
    if exists (
      select 1
      from public.replacement_orders replacement
      join public.production_pieces original_piece on original_piece.id = replacement.original_piece_id
      where original_piece.piece_uid = v_code
         or original_piece.traceability_code = v_code
         or original_piece.piece_code = v_code
         or original_piece.id::text = v_code
    ) then
      return jsonb_build_object('success', false, 'result_status', 'blocked', 'reason_code', 'ORIGINAL_PIECE_NOT_ALLOWED', 'message', 'Bipe a etiqueta da peca substituta. A peca original permanece reprovada.');
    end if;
    return jsonb_build_object('success', false, 'result_status', 'blocked', 'reason_code', 'CODE_NOT_FOUND', 'message', 'Codigo inexistente ou sem ordem de reposicao vinculada.');
  end if;

  select * into v_order from public.replacement_orders where id = v_order.id for update;
  perform 1
  from public.production_pieces piece
  where piece.id in (v_order.original_piece_id, v_order.replacement_piece_id)
  order by piece.id
  for update;
  select * into v_replacement_piece from public.production_pieces where id = v_order.replacement_piece_id;
  select * into v_original_piece from public.production_pieces where id = v_order.original_piece_id;

  if v_order.status in ('cancelled', 'Cancelada') then
    return jsonb_build_object('success', false, 'result_status', 'blocked', 'reason_code', 'ORDER_CANCELLED', 'message', 'Ordem de reposicao cancelada.');
  end if;
  if v_order.status in ('completed', 'Finalizada') then
    return jsonb_build_object('success', false, 'result_status', 'blocked', 'reason_code', 'STAGE_ALREADY_COMPLETED', 'message', 'Reposicao ja concluida.');
  end if;
  if v_order.status not in ('released', 'in_production') then
    return jsonb_build_object('success', false, 'result_status', 'blocked', 'reason_code', 'ORDER_NOT_RELEASED', 'message', 'Ordem ainda nao foi liberada pela gestao.');
  end if;
  if v_replacement_piece.id is null or v_replacement_piece.is_replacement is not true
     or v_replacement_piece.original_piece_id is distinct from v_original_piece.id then
    return jsonb_build_object('success', false, 'result_status', 'blocked', 'reason_code', 'INVALID_REPLACEMENT_PIECE', 'message', 'Peca substituta invalida ou sem vinculo com a original.');
  end if;
  if v_replacement_piece.is_blocked is true or v_replacement_piece.status = 'blocked' then
    return jsonb_build_object('success', false, 'result_status', 'blocked', 'reason_code', 'PIECE_BLOCKED', 'message', coalesce(v_replacement_piece.block_reason, 'Peca bloqueada para producao.'));
  end if;
  if v_replacement_piece.lot_id is null then
    return jsonb_build_object('success', false, 'result_status', 'blocked', 'reason_code', 'LOT_NOT_FOUND', 'message', 'Peca substituta sem lote produtivo.');
  end if;

  v_route := coalesce(v_replacement_piece.route_steps, v_original_piece.route_steps, array[]::text[]);
  v_completed := coalesce(v_replacement_piece.completed_steps, array[]::text[]);
  v_current_code := public.normalize_replacement_step_code(v_cell.name);

  select route.code, route.ord::integer, public.canonical_stage_label(route.step)
  into v_expected_code, v_expected_position, v_expected_label
  from (
    select step, public.normalize_replacement_step_code(step) as code, ord
    from unnest(v_route) with ordinality route_step(step, ord)
  ) route
  where not exists (
    select 1 from unnest(v_completed) completed_step
    where public.normalize_replacement_step_code(completed_step) = route.code
  )
  order by route.ord
  limit 1;

  if v_expected_code is null then
    return jsonb_build_object('success', false, 'result_status', 'blocked', 'reason_code', 'STAGE_ALREADY_COMPLETED', 'message', 'Todas as etapas obrigatorias desta reposicao ja foram concluidas.');
  end if;

  select min(route.ord)::integer into v_current_position
  from (
    select public.normalize_replacement_step_code(step) as code, ord
    from unnest(v_route) with ordinality route_step(step, ord)
  ) route
  where route.code = v_current_code;

  if v_current_position is null then
    return jsonb_build_object(
      'success', false, 'result_status', 'blocked', 'reason_code', 'STAGE_NOT_IN_ROUTE',
      'expected_stage', v_expected_label, 'expected_cell', v_expected_label,
      'message', format('A celula %s nao pertence a rota desta peca.', v_cell.name)
    );
  end if;
  if v_current_code <> v_expected_code then
    return jsonb_build_object(
      'success', false,
      'result_status', 'blocked',
      'reason_code', case when v_current_position > v_expected_position then 'PREVIOUS_STAGE_PENDING' else 'WRONG_CELL' end,
      'expected_stage', v_expected_label,
      'expected_cell', v_expected_label,
      'message', format('Etapa anterior pendente. A proxima baixa obrigatoria e %s.', v_expected_label)
    );
  end if;

  if exists (select 1 from public.production_stage_readings where client_event_id = p_client_event_id::text) then
    select event.result_payload into v_existing_result
    from public.production_collection_events event
    where event.client_event_id = p_client_event_id::text;
    return coalesce(v_existing_result, jsonb_build_object(
      'success', true, 'result_status', 'approved', 'reason_code', 'IDEMPOTENT_EVENT',
      'replacement_order_id', v_order.id, 'completed_stage', v_expected_label,
      'message', 'Evento ja confirmado anteriormente.'
    )) || jsonb_build_object('idempotent', true);
  end if;

  select route.code, public.canonical_stage_label(route.step)
  into v_next_code, v_next_label
  from (
    select step, public.normalize_replacement_step_code(step) as code, ord
    from unnest(v_route) with ordinality route_step(step, ord)
  ) route
  where route.ord > v_expected_position
    and not exists (
      select 1 from unnest(v_completed) completed_step
      where public.normalize_replacement_step_code(completed_step) = route.code
    )
  order by route.ord
  limit 1;
  v_is_last := v_next_code is null;

  insert into public.production_stage_readings (
    lot_id, piece_id, item_id, tag_value, reader_type, step_name, cell_name,
    station_name, machine_id, machine_name, operator, operator_id,
    operator_name_snapshot, user_id, shift, date, hour, status, event_type,
    client_event_id, notes, created_at, quantity, production_order_id,
    lot_code, order_number, customer_name, environment_name, operation_name,
    piece_code, traceability_type, general_lot_code
  ) values (
    v_replacement_piece.lot_id,
    v_replacement_piece.id,
    v_replacement_piece.legacy_production_lot_item_id,
    v_code,
    'keyboard_barcode',
    v_expected_code,
    v_cell.name,
    coalesce(v_session.station_name_snapshot, 'Posto de Reposicao'),
    v_machine.id,
    v_machine.name,
    v_operator.name,
    v_operator.id,
    v_operator.name,
    v_auth_user_id,
    coalesce(v_session.shift_snapshot, v_operator.shift, '1'),
    current_date,
    to_char(v_now, 'HH24:MI'),
    'approved',
    'replacement_approval',
    p_client_event_id::text,
    format('Baixa real da reposicao %s em %s.', coalesce(v_order.replacement_code, v_order.id::text), v_expected_label),
    v_now,
    1,
    v_replacement_piece.production_order_id,
    coalesce(v_replacement_piece.lot_code, v_order.lot_code),
    coalesce(v_replacement_piece.order_number, v_order.order_number),
    coalesce(v_replacement_piece.customer_name, v_order.customer_name),
    coalesce(v_replacement_piece.environment_name, v_order.environment_name),
    v_expected_code,
    case when v_is_last then 'approved_via_replacement' else 'replacement_stage' end,
    coalesce(v_replacement_piece.general_lot_code, v_order.general_lot_code)
  ) returning id into v_reading_id;

  update public.production_pieces
  set completed_steps = array_append(v_completed, v_expected_code),
      current_stage = coalesce(v_next_code, 'completed'),
      status = case when v_is_last then 'completed' else 'in_production' end,
      replacement_status = case when v_is_last then 'replaced' else 'in_production' end,
      updated_at = v_now
  where id = v_replacement_piece.id;

  update public.production_pieces
  set status = case when v_is_last then 'replaced' else 'rejected' end,
      replacement_status = case when v_is_last then 'replaced' else 'in_production' end,
      updated_at = v_now
  where id = v_original_piece.id;

  update public.replacement_orders
  set status = case when v_is_last then 'completed' else 'in_production' end,
      completed_at = case when v_is_last then coalesce(completed_at, v_now) else completed_at end,
      updated_at = v_now
  where id = v_order.id;

  if v_is_last then
    update public.quality_nonconformities
    set status = 'resolved',
        closed_at = coalesce(closed_at, v_now),
        closed_by = coalesce(closed_by, v_auth_user_id),
        updated_at = v_now
    where related_replacement_id = v_order.id
       or piece_id = v_original_piece.id;
  end if;

  v_lot_result := public.recalculate_replacement_lot_v2(v_replacement_piece.lot_id);
  if v_is_last and coalesce((v_lot_result ->> 'lot_completed')::boolean, false) then
    update public.production_stage_readings
    set notes = concat_ws(' ', notes, v_lot_result ->> 'message')
    where id = v_reading_id;
  end if;

  v_result := jsonb_build_object(
    'success', true,
    'result_status', 'approved',
    'reason_code', 'STAGE_COLLECTED_SUCCESSFULLY',
    'client_event_id', p_client_event_id,
    'reading_id', v_reading_id,
    'replacement_order_id', v_order.id,
    'replacement_piece_id', v_replacement_piece.id,
    'replacement_code', v_order.replacement_code,
    'completed_stage', v_expected_label,
    'next_stage', v_next_label,
    'is_last_stage', v_is_last,
    'replacement_completed', v_is_last,
    'lot', v_lot_result,
    'message', case
      when v_is_last then format('%s concluida. Reposicao finalizada com rastreabilidade.', v_expected_label)
      else format('%s concluida. Peca liberada para %s.', v_expected_label, v_next_label)
    end
  );

  insert into public.production_collection_events (
    client_event_id, raw_value, normalized_value, reader_type, operator_id,
    operator_name, cell_name, cell_id, shift, date, hour, status, result_status,
    reading_id, lot_id, production_order_id, payload, result_payload,
    created_at_client, processed_at, operator_session_id, device_id, piece_id,
    machine_id, machine_name, station_name, operation_name, lot_code,
    order_number, customer_name, environment_name, piece_code, general_lot_code
  ) values (
    p_client_event_id::text, v_code, upper(v_code), 'keyboard_barcode', v_operator.id,
    v_operator.name, v_cell.name, v_cell.id, coalesce(v_session.shift_snapshot, v_operator.shift),
    current_date, to_char(v_now, 'HH24:MI'), 'synced', 'approved',
    v_reading_id, v_replacement_piece.lot_id, v_replacement_piece.production_order_id,
    coalesce(p_payload, '{}'::jsonb) || jsonb_build_object('event_kind', 'replacement_stage'),
    v_result, coalesce(p_created_at_client, v_now), v_now, v_session.id, v_device_id,
    v_replacement_piece.id, v_machine.id, v_machine.name,
    coalesce(v_session.station_name_snapshot, 'Posto de Reposicao'), v_expected_code,
    coalesce(v_replacement_piece.lot_code, v_order.lot_code),
    coalesce(v_replacement_piece.order_number, v_order.order_number),
    coalesce(v_replacement_piece.customer_name, v_order.customer_name),
    coalesce(v_replacement_piece.environment_name, v_order.environment_name),
    v_replacement_piece.piece_code,
    coalesce(v_replacement_piece.general_lot_code, v_order.general_lot_code)
  );

  insert into public.system_audit_logs (
    user_id, user_name, action, entity, entity_id, page, route, device_id,
    session_id, success, metadata
  ) values (
    v_auth_user_id, v_operator.name,
    case when v_is_last then 'replacement_completed_via_station' else 'replacement_stage_collected_v2' end,
    'replacement_orders', v_order.id::text, 'Posto de Reposicao', '/reposicao/posto',
    v_device_id, v_session.id::text, true,
    jsonb_build_object(
      'operator_id', v_operator.id,
      'cell_id', v_cell.id,
      'cell_name', v_cell.name,
      'machine_id', v_machine.id,
      'machine_name', v_machine.name,
      'shift', v_session.shift_snapshot,
      'barcode', v_code,
      'client_event_id', p_client_event_id,
      'completed_stage', v_expected_label,
      'next_stage', v_next_label,
      'lot_result', v_lot_result
    )
  );

  perform realtime.send(
    jsonb_build_object(
      'replacement_order_id', v_order.id,
      'replacement_code', v_order.replacement_code,
      'lot_code', coalesce(v_order.lot_code, v_replacement_piece.lot_code),
      'completed_stage', v_expected_label,
      'next_stage', v_next_label,
      'message', v_result ->> 'message'
    ),
    'replacement_queue_updated',
    format('replacement:cell:%s', v_cell.id),
    true
  );

  if v_next_code is not null then
    select cell.id into v_next_cell_id
    from public.cells cell
    where cell.active = true
      and public.normalize_replacement_step_code(cell.name) = v_next_code
    order by cell.name
    limit 1;
    if v_next_cell_id is not null and v_next_cell_id <> v_cell.id then
      perform realtime.send(
        jsonb_build_object(
          'replacement_order_id', v_order.id,
          'replacement_code', v_order.replacement_code,
          'lot_code', coalesce(v_order.lot_code, v_replacement_piece.lot_code),
          'completed_stage', v_expected_label,
          'next_stage', v_next_label,
          'message', format('Nova reposicao disponivel na sua celula: %s - Lote %s.', coalesce(v_order.replacement_code, 'REP'), coalesce(v_order.lot_code, v_replacement_piece.lot_code, '-'))
        ),
        'replacement_available',
        format('replacement:cell:%s', v_next_cell_id),
        true
      );
    end if;
  end if;

  return v_result;
exception
  when unique_violation then
    select event.result_payload into v_existing_result
    from public.production_collection_events event
    where event.client_event_id = p_client_event_id::text;
    if v_existing_result is not null then
      return v_existing_result || jsonb_build_object('idempotent', true);
    end if;
    return jsonb_build_object(
      'success', false,
      'result_status', 'blocked',
      'reason_code', 'STAGE_ALREADY_COMPLETED',
      'expected_stage', v_expected_label,
      'message', 'A etapa foi concluida simultaneamente em outro posto. Atualize a fila.'
    );
end;
$function$

CREATE OR REPLACE FUNCTION public.collect_replacement_stage_v3(p_session_token text, p_barcode text, p_client_event_id uuid, p_device_id text, p_created_at_client timestamp with time zone, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
declare
  v_access jsonb;
begin
  v_access := private.validate_replacement_operator_session_v2(p_session_token, p_device_id, true);
  if coalesce((v_access ->> 'success')::boolean, false) is not true then
    return v_access || jsonb_build_object('result_status', 'blocked');
  end if;

  return public.collect_replacement_stage_v2(
    p_session_token,
    p_barcode,
    p_client_event_id,
    p_device_id,
    p_created_at_client,
    coalesce(p_payload, '{}'::jsonb)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.commit_pcp_import(p_batch_id uuid, p_order_code text, p_lot_code text, p_customer text, p_project_name text, p_mapping_profile text, p_mapping_version integer, p_rows jsonb, p_finalize boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row jsonb;
  v_current_user uuid := auth.uid();
  v_order_id uuid;
  v_first_order_id uuid;
  v_lot_id uuid;
  v_piece_id uuid;
  v_lot_item_id uuid;
  v_route_steps text[];
  v_row_order_code text;
  v_row_general_lot_code text;
  v_row_lot_code text;
  v_row_customer text;
  v_row_project text;
  v_barcode text;
  v_check_barcode text;
  v_route text;
  v_piece_code text;
  v_piece_name text;
  v_manual_joinery boolean;
  v_quantity integer;
  v_material text;
  v_color text;
  v_thickness numeric;
  v_width numeric;
  v_height numeric;
  v_environment text;
  v_module text;
  v_piece_uid text;
  v_suffix text;
  v_inserted_pieces integer := 0;
  v_inserted_rows integer := 0;
  v_order_count integer := 0;
  v_lot_count integer := 0;
  v_customer_count integer := 0;
  v_total_batch_pieces integer := 0;
  v_total_batch_rows integer := 0;
  v_existing_batch_id uuid;
  v_batch_general_lot_code text;
  v_existing_lot_batch_id uuid;
  v_existing_lot_customer text;
  i integer;
BEGIN
  IF v_current_user IS NULL OR public.get_my_role() NOT IN ('admin','manager','supervisor') THEN
    RAISE EXCEPTION 'Usuário sem permissão para confirmar importação PCP.' USING ERRCODE = '42501';
  END IF;

  SELECT general_lot_code INTO v_batch_general_lot_code
  FROM public.promob_import_batches
  WHERE id = p_batch_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Lote de importação % não localizado.', p_batch_id USING ERRCODE = 'P0008';
  END IF;

  IF p_rows IS NULL OR jsonb_typeof(p_rows) <> 'array' OR jsonb_array_length(p_rows) = 0 THEN
    RAISE EXCEPTION 'A importação PCP não contém linhas válidas.' USING ERRCODE = 'P0009';
  END IF;

  FOR v_row IN SELECT value FROM jsonb_array_elements(p_rows) LOOP
    v_row_order_code := COALESCE(NULLIF(TRIM(v_row->>'orderCode'), ''), NULLIF(TRIM(p_order_code), ''), 'PED-' || p_batch_id::text);
    v_row_general_lot_code := COALESCE(NULLIF(TRIM(v_row->>'generalLotCode'), ''), NULLIF(TRIM(p_lot_code), ''));
    v_row_lot_code := NULLIF(TRIM(v_row->>'clientLotCode'), '');
    v_row_customer := COALESCE(NULLIF(TRIM(v_row->>'customer'), ''), NULLIF(TRIM(p_customer), ''), 'Cliente não informado');
    v_row_project := COALESCE(NULLIF(TRIM(v_row->>'projectName'), ''), NULLIF(TRIM(p_project_name), ''), '');
    v_barcode := UPPER(TRIM(COALESCE(v_row->>'barcode', '')));
    v_check_barcode := UPPER(TRIM(COALESCE(v_row->>'checkBarcode', '')));
    v_route := TRIM(COALESCE(v_row->>'route', ''));
    v_piece_code := COALESCE(NULLIF(TRIM(v_row->>'pieceCode'), ''), v_barcode);
    v_piece_name := COALESCE(NULLIF(TRIM(v_row->>'pieceName'), ''), 'Sem nome');
    v_manual_joinery := COALESCE((v_row->>'manualJoinery')::boolean, false);
    v_quantity := 1;
    v_material := NULLIF(TRIM(v_row->>'material'), '');
    v_color := NULLIF(TRIM(v_row->>'color'), '');
    v_thickness := NULLIF(REPLACE(v_row->>'thickness', ',', '.'), '')::numeric;
    v_width := NULLIF(REPLACE(v_row->>'width', ',', '.'), '')::numeric;
    v_height := NULLIF(REPLACE(v_row->>'height', ',', '.'), '')::numeric;
    v_environment := NULLIF(TRIM(v_row->>'environmentName'), '');
    v_module := NULLIF(TRIM(v_row->>'moduleName'), '');

    IF v_barcode = '' THEN
      RAISE EXCEPTION 'Linha % sem código de barras.', COALESCE((v_row->>'row_number')::integer, v_inserted_rows + 1);
    END IF;
    IF v_row_general_lot_code IS NULL THEN
      RAISE EXCEPTION 'Linha % sem lote geral PCP.', COALESCE((v_row->>'row_number')::integer, v_inserted_rows + 1);
    END IF;
    IF v_batch_general_lot_code IS NULL OR v_batch_general_lot_code = '' THEN
      v_batch_general_lot_code := v_row_general_lot_code;
      UPDATE public.promob_import_batches
      SET general_lot_code = v_batch_general_lot_code
      WHERE id = p_batch_id;
    ELSIF v_batch_general_lot_code <> v_row_general_lot_code THEN
      RAISE EXCEPTION 'Linha % pertence ao lote geral %, mas esta importação é do lote geral %.',
        COALESCE((v_row->>'row_number')::integer, v_inserted_rows + 1),
        v_row_general_lot_code,
        v_batch_general_lot_code;
    END IF;
    IF v_row_lot_code IS NULL THEN
      RAISE EXCEPTION 'Linha % sem lote do cliente.', COALESCE((v_row->>'row_number')::integer, v_inserted_rows + 1);
    END IF;
    IF v_check_barcode <> '' AND v_check_barcode <> v_barcode THEN
      RAISE EXCEPTION 'Linha % com divergência entre código e conferência (% <> %).',
        COALESCE((v_row->>'row_number')::integer, v_inserted_rows + 1), v_barcode, v_check_barcode;
    END IF;

    INSERT INTO public.production_orders (
      order_code, system_order_number, order_number, customer_name,
      customer_legal_name, promob_project_name, status, created_by
    ) VALUES (
      v_row_order_code, v_row_order_code, v_row_order_code, v_row_customer,
      v_row_customer, v_row_project, 'planned', v_current_user
    )
    ON CONFLICT (order_code) DO UPDATE
    SET customer_name = CASE
          WHEN public.production_orders.customer_name = '' THEN EXCLUDED.customer_name
          ELSE public.production_orders.customer_name
        END,
        customer_legal_name = COALESCE(public.production_orders.customer_legal_name, EXCLUDED.customer_legal_name),
        promob_project_name = COALESCE(public.production_orders.promob_project_name, EXCLUDED.promob_project_name),
        updated_at = now()
    RETURNING id INTO v_order_id;

    v_first_order_id := COALESCE(v_first_order_id, v_order_id);

    SELECT l.id, l.pcp_import_batch_id,
           (SELECT pli.customer_name FROM public.production_lot_items pli WHERE pli.lot_id = l.id AND pli.customer_name IS NOT NULL LIMIT 1)
    INTO v_lot_id, v_existing_lot_batch_id, v_existing_lot_customer
    FROM public.production_lots l
    WHERE upper(l.lot_code) = upper(v_row_lot_code)
    FOR UPDATE;

    IF v_lot_id IS NULL THEN
      INSERT INTO public.production_lots (
        lot_code, order_id, production_order_id, order_number, customer_name,
        status, created_by, pcp_import_batch_id, actual_start
      ) VALUES (
        v_row_lot_code, v_order_id, v_order_id, v_row_order_code, v_row_customer,
        'planned', v_current_user, p_batch_id, NULL
      ) RETURNING id INTO v_lot_id;
    ELSE
      IF v_existing_lot_batch_id IS NOT NULL AND v_existing_lot_batch_id <> p_batch_id THEN
        RAISE EXCEPTION 'Lote do cliente % já pertence a outro lote geral PCP.', v_row_lot_code;
      END IF;
      IF v_existing_lot_customer IS NOT NULL AND lower(v_existing_lot_customer) <> lower(v_row_customer) THEN
        RAISE EXCEPTION 'Lote do cliente % está vinculado a % e não pode receber peças de %.',
          v_row_lot_code, v_existing_lot_customer, v_row_customer;
      END IF;
      UPDATE public.production_lots
      SET pcp_import_batch_id = p_batch_id,
          customer_name = COALESCE(NULLIF(customer_name, ''), v_row_customer),
          order_number = COALESCE(NULLIF(order_number, ''), v_row_order_code),
          updated_at = now()
      WHERE id = v_lot_id;
    END IF;

    INSERT INTO public.pcp_import_rows (
      batch_id, row_number, raw_cells, normalized_payload, barcode_raw,
      barcode_normalized, validation_status, validation_errors,
      mapping_version, row_hash
    ) VALUES (
      p_batch_id,
      COALESCE((v_row->>'row_number')::integer, v_inserted_rows + 1),
      COALESCE(v_row->'raw_cells', '[]'::jsonb),
      v_row,
      v_barcode,
      v_barcode,
      'valid',
      '[]'::jsonb,
      COALESCE(p_mapping_version, 1),
      md5(p_batch_id::text || ':' || v_row::text)
    )
    ON CONFLICT (batch_id, row_number) DO UPDATE
    SET raw_cells = EXCLUDED.raw_cells,
        normalized_payload = EXCLUDED.normalized_payload,
        barcode_raw = EXCLUDED.barcode_raw,
        barcode_normalized = EXCLUDED.barcode_normalized,
        validation_status = EXCLUDED.validation_status,
        validation_errors = EXCLUDED.validation_errors,
        mapping_version = EXCLUDED.mapping_version,
        row_hash = EXCLUDED.row_hash;

    v_route_steps := public.parse_pcp_route_tokens(v_route);
    IF v_manual_joinery THEN
      v_route_steps := array_prepend('joinery', array_remove(v_route_steps, 'joinery'));
    END IF;

    FOR i IN 1..v_quantity LOOP
      v_suffix := CASE WHEN v_quantity > 1 THEN '-' || i::text ELSE '' END;
      v_piece_uid := v_barcode || v_suffix;

      SELECT pcp_import_batch_id INTO v_existing_batch_id
      FROM public.production_pieces
      WHERE piece_uid = v_piece_uid;

      IF FOUND THEN
        IF v_existing_batch_id = p_batch_id THEN
          CONTINUE;
        END IF;
        RAISE EXCEPTION 'Código de barras % já pertence a outra importação PCP.', v_piece_uid;
      END IF;

      INSERT INTO public.production_lot_items (
        lot_id, item_code, product_code, product_name, current_step, status,
        lot_code, load_number, order_number, customer_name, environment_name,
        pieces_quantity
      ) VALUES (
        v_lot_id, v_piece_uid, v_piece_code, v_piece_name,
        COALESCE(v_route_steps[1], 'Importado'), 'pending',
        v_row_lot_code, NULL, v_row_order_code, v_row_customer, v_environment, 1
      ) RETURNING id INTO v_lot_item_id;

      v_piece_id := NULL;
      SELECT id INTO v_piece_id
      FROM public.production_pieces
      WHERE legacy_production_lot_item_id = v_lot_item_id
      ORDER BY created_at, id
      LIMIT 1
      FOR UPDATE;

      IF v_piece_id IS NULL THEN
        INSERT INTO public.production_pieces (
          piece_uid, traceability_code, production_order_id, lot_id,
          module_name, environment, piece_name, material, color,
          thickness, width, height, length, requires_joinery, manual_joinery,
          manual_joinery_reason, current_stage, status,
          source_origin, legacy_production_lot_item_id, route_steps,
          pcp_import_batch_id, created_by
        ) VALUES (
          v_piece_uid, v_piece_uid, v_order_id, v_lot_id,
          v_module, v_environment, v_piece_name, v_material, v_color,
          v_thickness, v_width, v_height, v_height, v_manual_joinery, v_manual_joinery,
          NULLIF(TRIM(v_row->>'manualJoineryReason'), ''),
          COALESCE(v_route_steps[1], 'created'), 'planned',
          CASE
            WHEN lower(COALESCE(v_row->>'sourceFormat', p_mapping_profile, '')) LIKE '%csv%' THEN 'csv'
            ELSE 'xlsx'
          END,
          v_lot_item_id, v_route_steps, p_batch_id, v_current_user
        ) RETURNING id INTO v_piece_id;
      ELSE
        UPDATE public.production_pieces
        SET piece_uid = v_piece_uid,
            traceability_code = v_piece_uid,
            production_order_id = v_order_id,
            lot_id = v_lot_id,
            module_name = v_module,
            environment = v_environment,
            piece_name = v_piece_name,
            material = v_material,
            color = v_color,
            thickness = v_thickness,
            width = v_width,
            height = v_height,
            length = v_height,
            requires_joinery = v_manual_joinery,
            manual_joinery = v_manual_joinery,
            manual_joinery_reason = NULLIF(TRIM(v_row->>'manualJoineryReason'), ''),
            current_stage = COALESCE(v_route_steps[1], 'created'),
            status = 'planned',
            source_origin = CASE
              WHEN lower(COALESCE(v_row->>'sourceFormat', p_mapping_profile, '')) LIKE '%csv%' THEN 'csv'
              ELSE 'xlsx'
            END,
            route_steps = v_route_steps,
            pcp_import_batch_id = p_batch_id,
            created_by = v_current_user,
            updated_at = now()
        WHERE id = v_piece_id;

        UPDATE public.production_events
        SET traceability_code = v_piece_uid,
            production_order_id = v_order_id,
            event_type = 'note',
            from_stage = NULL,
            to_stage = COALESCE(v_route_steps[1], 'created'),
            notes = 'Peça criada pela importação PCP.',
            metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object(
              'source', 'pcp_import',
              'pcp_import_batch_id', p_batch_id,
              'general_lot_code', v_row_general_lot_code,
              'client_lot_code', v_row_lot_code
            )
        WHERE piece_id = v_piece_id
          AND event_type = 'reading'
          AND operator_id IS NULL
          AND legacy_stage_reading_id IS NULL;
      END IF;

      INSERT INTO public.production_tags (
        lot_id, item_id, piece_id, tag_value, tag_type, active
      ) VALUES (
        v_lot_id, v_lot_item_id, v_piece_id, v_piece_uid,
        CASE WHEN v_manual_joinery THEN 'manual' ELSE 'barcode' END,
        true
      );

      v_inserted_pieces := v_inserted_pieces + 1;
    END LOOP;

    v_inserted_rows := v_inserted_rows + 1;
  END LOOP;

  SELECT count(*),
         count(DISTINCT p.production_order_id),
         count(DISTINCT p.lot_id),
         count(DISTINCT NULLIF(TRIM(l.customer_name), ''))
  INTO v_total_batch_pieces, v_order_count, v_lot_count, v_customer_count
  FROM public.production_pieces p
  LEFT JOIN public.production_lots l ON l.id = p.lot_id
  WHERE p.pcp_import_batch_id = p_batch_id;

  SELECT count(*) INTO v_total_batch_rows
  FROM public.pcp_import_rows
  WHERE batch_id = p_batch_id;

  SELECT production_order_id INTO v_first_order_id
  FROM public.production_pieces
  WHERE pcp_import_batch_id = p_batch_id
    AND production_order_id IS NOT NULL
  ORDER BY created_at, id
  LIMIT 1;

  UPDATE public.production_lots l
  SET planned_quantity = x.piece_count,
      pending_quantity = x.piece_count,
      progress_percent = 0,
      updated_at = now()
  FROM (
    SELECT lot_id, count(*)::numeric AS piece_count
    FROM public.production_pieces
    WHERE pcp_import_batch_id = p_batch_id
    GROUP BY lot_id
  ) x
  WHERE l.id = x.lot_id;

  UPDATE public.promob_import_batches
  SET status = CASE WHEN p_finalize THEN 'processed' ELSE 'parsed' END,
      imported_at = CASE WHEN p_finalize THEN now() ELSE imported_at END,
      validated_at = CASE WHEN p_finalize THEN now() ELSE validated_at END,
      customer_name = CASE WHEN v_order_count > 1 THEN 'Múltiplos clientes' ELSE p_customer END,
      promob_project_name = p_project_name,
      order_code = CASE WHEN v_order_count > 1 THEN 'Múltiplos pedidos' ELSE p_order_code END,
      generated_op_id = CASE WHEN v_order_count = 1 THEN v_first_order_id ELSE NULL END,
      total_parts = v_total_batch_pieces,
      client_lots_count = v_lot_count,
      customers_count = v_customer_count,
      source_format = p_mapping_profile,
      mapping_profile = p_mapping_profile,
      mapping_version = COALESCE(p_mapping_version, 1),
      total_lines = v_total_batch_rows,
      valid_lines = v_total_batch_rows,
      empty_lines = 0,
      duplicate_lines = 0,
      notes = format(
        'PCP consolidado: %s peças, %s pedido(s), %s lote(s).',
        v_total_batch_pieces, v_order_count, v_lot_count
      )
  WHERE id = p_batch_id;

  PERFORM public.refresh_pcp_batch_progress(p_batch_id);

  IF p_finalize THEN
    -- Gerar capas automaticamente ao finalizar
    PERFORM public.create_customer_covers_for_batch(p_batch_id);

    INSERT INTO public.pcp_import_logs (
      import_file_id, user_id, action, message, severity, metadata_json
    ) VALUES (
      p_batch_id,
      v_current_user,
      'PCP_IMPORT',
      format(
        'Importação PCP finalizada: %s peças, %s pedido(s), %s lote(s).',
        v_total_batch_pieces, v_order_count, v_lot_count
      ),
      'info',
      jsonb_build_object(
        'pieces_created', v_total_batch_pieces,
        'source_rows', v_total_batch_rows,
        'orders', v_order_count,
        'lots', v_lot_count,
        'pcp_import_batch_id', p_batch_id
      )
    );
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'batch_id', p_batch_id,
    'pieces_created', v_total_batch_pieces,
    'pieces_created_in_chunk', v_inserted_pieces,
    'rows_imported', v_total_batch_rows,
    'rows_imported_in_chunk', v_inserted_rows,
    'orders', v_order_count,
    'lots', v_lot_count,
    'finalized', p_finalize
  );
EXCEPTION WHEN OTHERS THEN
  UPDATE public.promob_import_batches
  SET status = 'error', error_message = SQLERRM
  WHERE id = p_batch_id;
  RAISE;
END;
$function$

CREATE OR REPLACE FUNCTION public.commit_pcp_import(p_batch_id uuid, p_order_code text, p_lot_code text, p_customer text, p_project_name text, p_mapping_profile text, p_mapping_version integer, p_rows jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_order_id uuid;
  v_lot_id uuid;
  v_row jsonb;
  v_piece_id uuid;
  v_lot_item_id uuid;
  v_route_steps text[];
  v_current_user uuid := auth.uid();
  v_barcode text;
  v_check_barcode text;
  v_route text;
  v_piece_code text;
  v_piece_name text;
  v_quantity integer;
  v_material text;
  v_color text;
  v_thickness numeric;
  v_width numeric;
  v_height numeric;
  v_length numeric;
  v_environment text;
  v_module text;
  v_step text;
  v_order_seq integer := 1;
  v_inserted_pieces integer := 0;
  v_inserted_items integer := 0;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.promob_import_batches WHERE id = p_batch_id) THEN
    RAISE EXCEPTION 'Lote de importação % não localizado', p_batch_id USING ERRCODE = 'P0008';
  END IF;

  -- 1. Resolver/Criar Pedido de Produção
  SELECT id INTO v_order_id FROM public.production_orders WHERE UPPER(order_code) = UPPER(p_order_code) LIMIT 1;
  IF v_order_id IS NULL THEN
    INSERT INTO public.production_orders (
      order_code, system_order_number, customer_name, project_name, status, created_by
    ) VALUES (
      p_order_code, p_order_code, p_customer, p_project_name, 'planned', v_current_user
    ) RETURNING id INTO v_order_id;
  END IF;

  -- 2. Resolver/Criar Lote de Produção
  SELECT id INTO v_lot_id FROM public.production_lots WHERE UPPER(lot_code) = UPPER(p_lot_code) LIMIT 1;
  IF v_lot_id IS NULL THEN
    INSERT INTO public.production_lots (
      lot_code, order_id, production_order_id, status, created_by, pcp_import_batch_id, customer_name
    ) VALUES (
      p_lot_code, v_order_id, v_order_id, 'planned', v_current_user, p_batch_id, p_customer
    ) RETURNING id INTO v_lot_id;
  ELSE
    UPDATE public.production_lots 
    SET status = 'planned', pcp_import_batch_id = p_batch_id, customer_name = COALESCE(customer_name, p_customer) 
    WHERE id = v_lot_id;
  END IF;

  -- 3. Processar cada linha de peça
  FOR v_row IN SELECT * FROM jsonb_array_elements(p_rows) LOOP
    v_barcode := TRIM(v_row->>'barcode');
    v_check_barcode := TRIM(v_row->>'checkBarcode');
    v_route := TRIM(v_row->>'route');
    v_piece_code := TRIM(v_row->>'pieceCode');
    v_piece_name := COALESCE(NULLIF(TRIM(v_row->>'pieceName'), ''), 'Sem Nome');
    v_quantity := GREATEST(COALESCE((v_row->>'quantity')::integer, 1), 1);
    v_material := COALESCE(NULLIF(TRIM(v_row->>'material'), ''), 'MDF');
    v_color := COALESCE(NULLIF(TRIM(v_row->>'color'), ''), 'Padrão');
    v_thickness := COALESCE((v_row->>'thickness')::numeric, 15);
    v_width := COALESCE((v_row->>'width')::numeric, 0);
    v_height := COALESCE((v_row->>'height')::numeric, 0);
    v_length := COALESCE(v_height, 0);
    v_environment := TRIM(v_row->>'environmentName');
    v_module := TRIM(v_row->>'moduleName');

    IF v_barcode IS NULL OR v_barcode = '' THEN
      CONTINUE;
    END IF;

    -- Parser de roteamento
    v_route_steps := public.parse_pcp_route_tokens(v_route);

    -- Inserir rota no production_routes se não existir
    v_order_seq := 1;
    FOREACH v_step IN ARRAY v_route_steps LOOP
      INSERT INTO public.production_routes (
        lot_id, step_name, step_order, required, status
      ) VALUES (
        v_lot_id, 
        COALESCE((SELECT name FROM public.routing_steps WHERE code = v_step), v_step),
        v_order_seq, 
        true, 
        'planned'
      ) ON CONFLICT DO NOTHING;
      v_order_seq := v_order_seq + 1;
    END LOOP;

    -- Unidades de peças
    FOR i IN 1..v_quantity LOOP
      DECLARE
        v_suffix text := CASE WHEN v_quantity > 1 THEN '-' || i::text ELSE '' END;
        v_piece_uid text := v_barcode || v_suffix;
        v_traceability text := v_barcode || v_suffix;
      BEGIN
        INSERT INTO public.pcp_import_rows (
          batch_id, row_number, raw_cells, normalized_payload, barcode_raw, barcode_normalized,
          validation_status, mapping_version, row_hash
        ) VALUES (
          p_batch_id, (v_row->>'row_number')::integer, v_row->'raw_cells', v_row, v_barcode, v_barcode,
          'valid', p_mapping_version, md5(v_row::text)
        );

        INSERT INTO public.production_lot_items (
          lot_id, product_code, product_name, quantity, status, current_step,
          material, color, width, height, thickness, created_by
        ) VALUES (
          v_lot_id, v_piece_code, v_piece_name, 1, 'planned', 'Importado',
          v_material, v_color, v_width, v_height, v_thickness, v_current_user
        ) RETURNING id INTO v_lot_item_id;

        v_inserted_items := v_inserted_items + 1;

        INSERT INTO public.production_pieces (
          piece_uid, traceability_code, production_order_id, lot_id,
          module_name, environment, piece_name, material, color,
          thickness, width, height, length,
          current_stage, status, source_origin,
          legacy_production_lot_item_id, route_steps, created_by
        ) VALUES (
          v_piece_uid, v_traceability, v_order_id, v_lot_id,
          v_module, v_environment, v_piece_name, v_material, v_color,
          v_thickness, v_width, v_height, v_length,
          COALESCE((SELECT name FROM public.routing_steps WHERE code = v_route_steps[1]), v_route_steps[1], 'Corte'), 
          'planned', 'xlsx',
          v_lot_item_id, v_route_steps, v_current_user
        ) ON CONFLICT (piece_uid) DO UPDATE SET
          material = EXCLUDED.material,
          color = EXCLUDED.color,
          thickness = EXCLUDED.thickness,
          width = EXCLUDED.width,
          height = EXCLUDED.height,
          length = EXCLUDED.length,
          route_steps = EXCLUDED.route_steps
        RETURNING id INTO v_piece_id;

        v_inserted_pieces := v_inserted_pieces + 1;
      END;
    END LOOP;
  END LOOP;

  -- Criar capas de cliente para o lote
  PERFORM public.create_customer_covers_for_batch(p_batch_id);

  RETURN jsonb_build_object(
    'success', true,
    'order_id', v_order_id,
    'lot_id', v_lot_id,
    'inserted_pieces', v_inserted_pieces,
    'inserted_items', v_inserted_items
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.complete_piece_replacement(p_order_id uuid, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_order public.replacement_orders%rowtype;
  v_replacement public.production_pieces%rowtype;
  v_user_id uuid := auth.uid();
  v_required_steps text[];
  v_completed_steps text[];
  v_pending_steps text[];
  v_notes text := nullif(trim(p_payload->>'notes'), '');
begin
  select * into v_order
  from public.replacement_orders
  where id = p_order_id
  for update;

  if v_order.id is null then
    raise exception 'Ordem de reposição não encontrada.';
  end if;

  if v_order.status = 'completed' then
    return jsonb_build_object(
      'success', true,
      'already_completed', true,
      'status', 'completed'
    );
  end if;

  if v_order.status not in ('approved', 'released', 'in_production') then
    raise exception 'A reposição não está liberada para conclusão. Status atual: %', v_order.status;
  end if;

  if v_order.replacement_piece_id is null then
    raise exception 'A ordem não possui peça substituta vinculada.';
  end if;

  select * into v_replacement
  from public.production_pieces
  where id = v_order.replacement_piece_id
  for update;

  if v_replacement.id is null then
    raise exception 'Peça substituta não encontrada.';
  end if;

  v_required_steps := public.canonicalize_production_route(
    coalesce(v_replacement.route_steps, '{}'::text[])
    || case when coalesce(v_replacement.requires_cut, false) then array['cut']::text[] else '{}'::text[] end
    || case when coalesce(v_replacement.requires_edge, false) then array['edge']::text[] else '{}'::text[] end
    || case when coalesce(v_replacement.requires_cnc, false) then array['cnc']::text[] else '{}'::text[] end
    || case when coalesce(v_replacement.requires_joinery, false) or coalesce(v_replacement.manual_joinery, false)
      then array['joinery']::text[] else '{}'::text[] end
    || case when coalesce(v_replacement.requires_separation, false) then array['separation']::text[] else '{}'::text[] end
    || case when coalesce(v_replacement.requires_packaging, false) then array['packaging']::text[] else '{}'::text[] end
  );
  v_completed_steps := public.canonicalize_production_route(v_replacement.completed_steps);

  select coalesce(array_agg(required.step_code order by required.ordinality), '{}'::text[])
  into v_pending_steps
  from unnest(v_required_steps) with ordinality required(step_code, ordinality)
  left join public.production_stage_policies policy
    on policy.stage_code = required.step_code
  where coalesce(policy.traceable_collection_required, true)
    and not (required.step_code = any(v_completed_steps));

  if cardinality(v_pending_steps) > 0 then
    raise exception
      'A peça substituta ainda possui etapas obrigatórias pendentes: %.',
      array_to_string(v_pending_steps, ', ');
  end if;

  update public.production_pieces
  set status = 'replaced',
      replacement_status = 'replaced',
      updated_at = now()
  where id = v_order.original_piece_id;

  update public.production_pieces
  set status = 'completed',
      production_status = 'completed',
      replacement_status = 'replaced',
      current_stage = 'Concluída',
      updated_at = now()
  where id = v_order.replacement_piece_id;

  update public.replacement_orders
  set status = 'completed',
      completed_at = coalesce(completed_at, now()),
      notes = coalesce(v_notes, notes),
      updated_at = now()
  where id = p_order_id;

  update public.quality_nonconformities
  set status = 'closed',
      closed_at = coalesce(closed_at, now()),
      closed_by = coalesce(closed_by, v_user_id),
      updated_at = now()
  where related_replacement_id = p_order_id
    and status <> 'closed';

  return jsonb_build_object(
    'success', true,
    'status', 'completed',
    'replacement_piece_id', v_order.replacement_piece_id,
    'restored_approved_accounting', true
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.compute_report_next_run(p_frequency text, p_time_local time without time zone, p_timezone text DEFAULT 'America/Sao_Paulo'::text, p_from timestamp with time zone DEFAULT now())
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_local_now timestamp := p_from AT TIME ZONE p_timezone;
  v_candidate timestamp;
BEGIN
  v_candidate := date_trunc('day', v_local_now) + p_time_local;

  IF p_frequency = 'monthly' THEN
    IF v_candidate <= v_local_now THEN
      v_candidate := v_candidate + interval '1 month';
    END IF;
  ELSIF p_frequency = 'weekly' THEN
    IF v_candidate <= v_local_now THEN
      v_candidate := v_candidate + interval '7 days';
    END IF;
  ELSE
    IF v_candidate <= v_local_now THEN
      v_candidate := v_candidate + interval '1 day';
    END IF;
    IF p_frequency = 'workdays' THEN
      WHILE extract(isodow FROM v_candidate) IN (6, 7) LOOP
        v_candidate := v_candidate + interval '1 day';
      END LOOP;
    END IF;
  END IF;

  RETURN v_candidate AT TIME ZONE p_timezone;
END;
$function$

CREATE OR REPLACE FUNCTION public.correct_production_downtime(p_occurrence_id uuid, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_started_at timestamptz := (p_payload->>'started_at')::timestamptz;
  v_ended_at timestamptz := (p_payload->>'ended_at')::timestamptz;
  v_duration numeric;
BEGIN
  IF v_started_at IS NOT NULL AND v_ended_at IS NOT NULL THEN
    IF v_ended_at <= v_started_at THEN
      RAISE EXCEPTION 'Horário final deve ser maior que o horário inicial.';
    END IF;
    v_duration := ROUND(EXTRACT(EPOCH FROM (v_ended_at - v_started_at)) / 60.0, 2);
  ELSE
    v_duration := (p_payload->>'duration_minutes')::numeric;
  END IF;

  UPDATE public.occurrences
  SET started_at = COALESCE(v_started_at, started_at),
      ended_at = COALESCE(v_ended_at, ended_at),
      duration_minutes = COALESCE(v_duration, duration_minutes),
      downtime = COALESCE(v_duration, downtime),
      reason = COALESCE(p_payload->>'reason', reason),
      notes = COALESCE(p_payload->>'notes', notes),
      updated_at = now()
  WHERE id = p_occurrence_id;

  RETURN jsonb_build_object('success', true, 'occurrence_id', p_occurrence_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.create_customer_covers_for_batch_impl(p_batch_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_batch_code text;
  v_rec record;
  v_cover_id uuid;
  v_hash text;
  v_cover_code text;
  v_customer_clean text;
BEGIN
  -- Obter o código do lote geral/batch
  SELECT general_lot_code INTO v_batch_code
  FROM public.promob_import_batches
  WHERE id = p_batch_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Lote de importação % não encontrado.', p_batch_id;
  END IF;

  -- Percorrer os clientes do lote
  FOR v_rec IN 
    SELECT DISTINCT customer_name 
    FROM public.production_lots 
    WHERE pcp_import_batch_id = p_batch_id
  LOOP
    v_customer_clean := btrim(v_rec.customer_name);

    -- Ignorar clientes vazios ou não informados agrupados (isolamos por lote de forma controlada)
    IF v_customer_clean IS NULL OR v_customer_clean = '' OR v_customer_clean = 'Cliente não informado' THEN
      -- Criar uma capa exclusiva para cada lote individual sem cliente válido
      FOR v_rec IN 
        SELECT id, lot_code, customer_name
        FROM public.production_lots 
        WHERE pcp_import_batch_id = p_batch_id
          AND (customer_name IS NULL OR btrim(customer_name) = '' OR btrim(customer_name) = 'Cliente não informado')
      LOOP
        v_customer_clean := COALESCE(NULLIF(btrim(v_rec.customer_name), ''), 'Cliente não informado');
        v_hash := substring(md5(p_batch_id::text || ':' || v_rec.lot_code), 1, 8);
        v_cover_code := 'CAP-' || COALESCE(v_batch_code, 'PCP') || '-' || v_hash;

        INSERT INTO public.customer_covers (
          pcp_import_batch_id, general_lot_code, customer_name_exact, cover_code, status
        ) VALUES (
          p_batch_id, COALESCE(v_batch_code, 'PCP'), v_customer_clean || ' (' || v_rec.lot_code || ')', v_cover_code, 'planned'
        )
        ON CONFLICT (pcp_import_batch_id, customer_name_exact) DO UPDATE
        SET general_lot_code = EXCLUDED.general_lot_code
        RETURNING id INTO v_cover_id;

        UPDATE public.production_lots
        SET customer_cover_id = v_cover_id
        WHERE id = v_rec.id;
      END LOOP;
    ELSE
      -- Gerar hash determinístico baseado no batch e no nome do cliente
      v_hash := substring(md5(p_batch_id::text || ':' || v_customer_clean), 1, 8);
      v_cover_code := 'CAP-' || COALESCE(v_batch_code, 'PCP') || '-' || v_hash;

      INSERT INTO public.customer_covers (
        pcp_import_batch_id, general_lot_code, customer_name_exact, cover_code, status
      ) VALUES (
        p_batch_id, COALESCE(v_batch_code, 'PCP'), v_customer_clean, v_cover_code, 'planned'
      )
      ON CONFLICT (pcp_import_batch_id, customer_name_exact) DO UPDATE
      SET general_lot_code = EXCLUDED.general_lot_code
      RETURNING id INTO v_cover_id;

      -- Associar os lotes correspondentes a essa capa
      UPDATE public.production_lots
      SET customer_cover_id = v_cover_id
      WHERE pcp_import_batch_id = p_batch_id
        AND btrim(customer_name) = v_customer_clean;

      -- Registrar evento
      INSERT INTO public.customer_cover_events (cover_id, event_type, metadata)
      VALUES (v_cover_id, 'created', jsonb_build_object('auto_created', true));
    END IF;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_customer_covers_for_batch(p_batch_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if auth.role() <> 'service_role'
     and not (
       public.has_permission('manage_pcp')
       or public.has_permission('manage_packaging')
     ) then
    raise exception 'CUSTOMER_COVER_MANAGE_PERMISSION_REQUIRED' using errcode = '42501';
  end if;

  perform public.create_customer_covers_for_batch_impl(p_batch_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.delete_traceability_test_data()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_deleted_readings integer := 0;
  v_deleted_entries integer := 0;
  v_deleted_occurrences integer := 0;
  v_deleted_tags integer := 0;
  v_deleted_items integer := 0;
  v_deleted_routes integer := 0;
  v_deleted_lots integer := 0;
  v_deleted_orders integer := 0;
  v_deleted_logs integer := 0;
BEGIN
  -- 1. Verificar permissão (apenas admins e gestores)
  IF auth.uid() IS NULL OR get_my_role() NOT IN ('admin','manager') THEN
    RETURN jsonb_build_object('success', false, 'message', 'Usuário sem permissão para apagar dados de teste.');
  END IF;

  -- 2. Apagar leituras de produção vinculadas a tags de teste ou lotes de teste
  DELETE FROM production_stage_readings 
  WHERE tag_value LIKE 'BARCODE-TEST-%' 
     OR tag_value LIKE 'QRCODE-TEST-%' 
     OR tag_value LIKE 'RFID-TEST-%'
     OR lot_id IN (
       SELECT id FROM production_lots WHERE lot_code LIKE 'LOTE-TEST-%'
     );
  GET DIAGNOSTICS v_deleted_readings = ROW_COUNT;

  -- 3. Apagar ocorrências vinculadas aos lotes de teste
  DELETE FROM occurrences 
  WHERE notes LIKE '%LOTE-TEST-%' 
     OR notes LIKE '%PECA-TEST-%' 
     OR lot_id IN (
       SELECT id FROM production_lots WHERE lot_code LIKE 'LOTE-TEST-%'
     );
  GET DIAGNOSTICS v_deleted_occurrences = ROW_COUNT;

  -- 4. Apagar entradas de produção geradas automaticamente
  DELETE FROM production_entries 
  WHERE notes LIKE 'Coleta produtiva - tag BARCODE-TEST-%' 
     OR notes LIKE 'Coleta produtiva - tag QRCODE-TEST-%' 
     OR notes LIKE 'Coleta produtiva - tag RFID-TEST-%' 
     OR notes LIKE 'Reprovação vinculada a tag BARCODE-TEST-%'
     OR notes LIKE 'Reprovação vinculada a tag QRCODE-TEST-%'
     OR notes LIKE 'Reprovação vinculada a tag RFID-TEST-%'
     OR notes LIKE '%PECA-TEST-%' 
     OR notes LIKE '%LOTE-TEST-%';
  GET DIAGNOSTICS v_deleted_entries = ROW_COUNT;

  -- 5. Apagar logs de rastreabilidade
  DELETE FROM traceability_logs 
  WHERE details->>'tag' LIKE 'BARCODE-TEST-%' 
     OR details->>'tag' LIKE 'QRCODE-TEST-%' 
     OR details->>'tag' LIKE 'RFID-TEST-%'
     OR entity_id IN (
       SELECT id FROM production_lot_items WHERE item_code LIKE 'PECA-TEST-%'
     );
  GET DIAGNOSTICS v_deleted_logs = ROW_COUNT;

  -- 6. Apagar tags de teste
  DELETE FROM production_tags 
  WHERE tag_value LIKE 'BARCODE-TEST-%' 
     OR tag_value LIKE 'QRCODE-TEST-%' 
     OR tag_value LIKE 'RFID-TEST-%'
     OR lot_id IN (
       SELECT id FROM production_lots WHERE lot_code LIKE 'LOTE-TEST-%'
     );
  GET DIAGNOSTICS v_deleted_tags = ROW_COUNT;

  -- 7. Apagar itens do lote de teste
  DELETE FROM production_lot_items 
  WHERE item_code LIKE 'PECA-TEST-%' 
     OR lot_id IN (
       SELECT id FROM production_lots WHERE lot_code LIKE 'LOTE-TEST-%'
     );
  GET DIAGNOSTICS v_deleted_items = ROW_COUNT;

  -- 8. Apagar rotas de teste
  DELETE FROM production_routes 
  WHERE lot_id IN (
     SELECT id FROM production_lots WHERE lot_code LIKE 'LOTE-TEST-%'
  );
  GET DIAGNOSTICS v_deleted_routes = ROW_COUNT;

  -- 9. Apagar lotes de teste
  DELETE FROM production_lots 
  WHERE lot_code LIKE 'LOTE-TEST-%';
  GET DIAGNOSTICS v_deleted_lots = ROW_COUNT;

  -- 10. Apagar ordens de teste
  DELETE FROM production_orders 
  WHERE order_code LIKE 'ORDEM-TEST-%';
  GET DIAGNOSTICS v_deleted_orders = ROW_COUNT;

  RETURN jsonb_build_object(
    'success', true,
    'message', 'Dados de teste limpos com sucesso.',
    'deleted_readings', v_deleted_readings,
    'deleted_entries', v_deleted_entries,
    'deleted_occurrences', v_deleted_occurrences,
    'deleted_tags', v_deleted_tags,
    'deleted_items', v_deleted_items,
    'deleted_routes', v_deleted_routes,
    'deleted_lots', v_deleted_lots,
    'deleted_orders', v_deleted_orders,
    'deleted_logs', v_deleted_logs
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.delete_user_from_auth(target_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth', 'pg_temp'
AS $function$
declare
  v_target_role text;
  v_target_active boolean;
begin
  if auth.uid() is null or public.get_my_role() <> 'admin' then
    raise exception 'Apenas administradores ativos podem excluir usuários do sistema.'
      using errcode = '42501';
  end if;

  if target_user_id = auth.uid() then
    raise exception 'Não é permitido excluir a própria conta administrativa.'
      using errcode = '42501';
  end if;

  select role, active
    into v_target_role, v_target_active
  from public.profiles
  where id = target_user_id;

  if not found then
    raise exception 'Usuário não encontrado.' using errcode = 'P0002';
  end if;

  if v_target_role = 'admin'
     and v_target_active is true
     and (
       select count(*)
       from public.profiles
       where role = 'admin' and active is true
     ) <= 1 then
    raise exception 'O sistema deve manter ao menos um administrador ativo.'
      using errcode = '42501';
  end if;

  delete from public.report_schedule_recipients where profile_id = target_user_id;
  delete from public.email_recipient_group_members where profile_id = target_user_id;
  update public.alert_logs set created_by = null where created_by = target_user_id;
  update public.alert_logs set resolved_by = null where resolved_by = target_user_id;
  update public.report_schedule_runs set requested_by = null where requested_by = target_user_id;
  update public.report_deliveries set profile_id = null where profile_id = target_user_id;
  delete from auth.users where id = target_user_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_registered_report_recipients()
 RETURNS trigger
