CREATE OR REPLACE FUNCTION public.enforce_replacement_approval_permission()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_allowed boolean := false;
BEGIN
  -- Chamadas administrativas diretas, migrações e service role não possuem
  -- auth.uid(). A validação abaixo protege as chamadas efetuadas pelo cliente.
  IF v_user_id IS NULL THEN
    RETURN NEW;
  END IF;

  IF OLD.status IN ('requested', 'under_review')
     AND NEW.status IN ('approved', 'released', 'in_production', 'completed') THEN
    SELECT EXISTS (
      SELECT 1
      FROM public.profiles p
      WHERE p.id = v_user_id
        AND COALESCE(p.active, true) IS TRUE
        AND (
          lower(COALESCE(p.role, '')) IN ('admin', 'manager')
          OR lower(COALESCE(p.permissions->>'approve_replacements', 'false')) = 'true'
        )
    )
    INTO v_allowed;

    IF NOT v_allowed THEN
      RAISE EXCEPTION 'Usuário sem permissão para aprovar reposições.'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.enrich_production_entry_context()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tag text;
  v_lot production_lots%ROWTYPE;
  v_order production_orders%ROWTYPE;
  v_item production_order_items%ROWTYPE;
BEGIN
  NEW.production_order_id := COALESCE(NEW.production_order_id, NEW.order_id);
  NEW.order_id := COALESCE(NEW.order_id, NEW.production_order_id);
  IF NEW.lot_id IS NULL AND NEW.notes ~* 'tag ' THEN
    v_tag := UPPER(TRIM(regexp_replace(NEW.notes, '^.*tag ', '', 'i')));
    SELECT pl.* INTO v_lot FROM production_tags pt JOIN production_lots pl ON pl.id = pt.lot_id
    WHERE pt.tag_value = v_tag LIMIT 1;
    NEW.lot_id := COALESCE(NEW.lot_id, v_lot.id);
  END IF;
  IF NEW.lot_id IS NOT NULL THEN
    SELECT * INTO v_lot FROM production_lots WHERE id = NEW.lot_id;
    NEW.production_order_id := COALESCE(NEW.production_order_id, v_lot.production_order_id, v_lot.order_id);
    NEW.order_id := COALESCE(NEW.order_id, NEW.production_order_id);
    NEW.lot_code := COALESCE(NULLIF(NEW.lot_code,''), v_lot.lot_code);
    NEW.product_code := COALESCE(NULLIF(NEW.product_code,''), v_lot.product_code);
    NEW.product_name := COALESCE(NULLIF(NEW.product_name,''), v_lot.product_name);
    NEW.product_description := COALESCE(NULLIF(NEW.product_description,''), v_lot.product_description);
    NEW.process_step := COALESCE(NULLIF(NEW.process_step,''), v_lot.current_step, v_lot.current_stage);
  END IF;
  IF NEW.production_order_id IS NOT NULL THEN
    SELECT * INTO v_order FROM production_orders WHERE id = NEW.production_order_id;
    NEW.system_order_number := COALESCE(NULLIF(NEW.system_order_number,''), v_order.system_order_number);
    NEW.customer_order_number := COALESCE(NULLIF(NEW.customer_order_number,''), v_order.customer_order_number);
    NEW.order_number := COALESCE(NULLIF(NEW.order_number,''), v_order.order_number, v_order.order_code);
    NEW.load_number := COALESCE(NULLIF(NEW.load_number,''), v_order.load_number);
    NEW.customer_code := COALESCE(NULLIF(NEW.customer_code,''), v_order.customer_code);
    NEW.customer_legal_name := COALESCE(NULLIF(NEW.customer_legal_name,''), v_order.customer_legal_name, v_order.customer_name);
    NEW.customer_trade_name := COALESCE(NULLIF(NEW.customer_trade_name,''), v_order.customer_trade_name, v_order.customer_name);
    NEW.customer_name := COALESCE(NULLIF(NEW.customer_name,''), v_order.customer_trade_name, v_order.customer_name);
    NEW.cnpj := COALESCE(NULLIF(NEW.cnpj,''), v_order.cnpj);
    NEW.finalization_date := COALESCE(NEW.finalization_date, v_order.finalization_date);
    NEW.city := COALESCE(NULLIF(NEW.city,''), v_order.city);
    NEW.state := COALESCE(NULLIF(NEW.state,''), v_order.state);
    NEW.delivery_region := COALESCE(NULLIF(NEW.delivery_region,''), v_order.delivery_region);
  END IF;
  IF NEW.order_item_id IS NOT NULL THEN
    SELECT * INTO v_item FROM production_order_items WHERE id = NEW.order_item_id;
    NEW.product_code := COALESCE(NULLIF(NEW.product_code,''), v_item.product_code);
    NEW.product_name := COALESCE(NULLIF(NEW.product_name,''), v_item.product_name);
    NEW.product_description := COALESCE(NULLIF(NEW.product_description,''), v_item.product_description);
    NEW.route_code := COALESCE(NULLIF(NEW.route_code,''), v_item.route_code);
    NEW.route_name := COALESCE(NULLIF(NEW.route_name,''), v_item.route_name);
    NEW.mirror_quantity := COALESCE(NEW.mirror_quantity, v_item.mirror_quantity, 0);
    NEW.pallet_number := COALESCE(NULLIF(NEW.pallet_number,''), v_item.pallet_number);
  END IF;
  NEW.traceability_status := CASE WHEN COALESCE(NEW.production_order_id, NEW.lot_id, NEW.order_item_id) IS NULL THEN 'limited' ELSE 'resolved' END;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.enrich_production_entry_metric()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
DECLARE
  v_item_id uuid;
  v_item_sheet numeric := 0;
  v_item_edge numeric := 0;
  v_item_pieces numeric := 0;
  v_item_covers numeric := 0;
  v_inferred_unit text;
  v_unit text;
  v_realized numeric;
  v_base numeric;
BEGIN
  SELECT pli.id, pli.sheet_count, pli.edge_meters, pli.pieces_quantity, pli.covers_quantity
  INTO v_item_id, v_item_sheet, v_item_edge, v_item_pieces, v_item_covers
  FROM public.production_stage_readings psr
  JOIN public.production_lot_items pli ON pli.id = psr.item_id
  WHERE psr.client_event_id IS NOT NULL
    AND psr.client_event_id = NEW.client_event_id
  ORDER BY psr.created_at DESC
  LIMIT 1;

  IF v_item_id IS NULL AND NEW.order_item_id IS NOT NULL THEN
    SELECT id, sheet_count, edge_meters, pieces_quantity, covers_quantity
    INTO v_item_id, v_item_sheet, v_item_edge, v_item_pieces, v_item_covers
    FROM public.production_order_items
    WHERE id = NEW.order_item_id
    LIMIT 1;
  END IF;

  v_inferred_unit := public.production_metric_unit_for_cell(
    NEW.cell,
    COALESCE(NEW.operation_name, NEW.process_step),
    NEW.operation_name
  );

  v_unit := CASE
    WHEN NEW.metric_unit IN ('sheets','meters','covers') THEN NEW.metric_unit
    WHEN NEW.metric_unit = 'pieces' AND v_inferred_unit = 'pieces' THEN 'pieces'
    ELSE v_inferred_unit
  END;

  NEW.metric_unit := v_unit;
  NEW.metric_unit_label := public.production_metric_unit_label(v_unit);
  NEW.metric_name := COALESCE(NULLIF(NEW.metric_name, ''), public.production_metric_name_for_unit(v_unit, NEW.cell));
  NEW.planned_target := COALESCE(NULLIF(NEW.planned_target, 0), NEW.target, 0);
  NEW.planned_capacity := COALESCE(NEW.planned_capacity, 0);

  v_realized := COALESCE(NULLIF(NEW.realized_quantity, 0), 0);

  IF v_realized = 0 THEN
    IF v_unit = 'meters' THEN
      v_realized := COALESCE(NULLIF(NEW.edge_meters, 0), NULLIF(v_item_edge, 0), GREATEST(COALESCE(NEW.produced, 0), 1));
      NEW.edge_meters := COALESCE(NULLIF(NEW.edge_meters, 0), NULLIF(v_item_edge, 0), v_realized);
    ELSIF v_unit = 'sheets' THEN
      v_realized := COALESCE(NULLIF(NEW.sheet_count, 0), NULLIF(v_item_sheet, 0), CASE WHEN NEW.client_event_id IS NULL THEN COALESCE(NEW.produced, 0) ELSE 0 END);
      NEW.sheet_count := COALESCE(NULLIF(NEW.sheet_count, 0), NULLIF(v_item_sheet, 0), v_realized);
    ELSIF v_unit = 'covers' THEN
      v_realized := COALESCE(NULLIF(NEW.covers_quantity, 0), NULLIF(v_item_covers, 0), COALESCE(NEW.produced, 0));
      NEW.covers_quantity := COALESCE(NULLIF(NEW.covers_quantity, 0), NULLIF(v_item_covers, 0), v_realized);
    ELSE
      v_realized := COALESCE(NULLIF(NEW.pieces_quantity, 0), NULLIF(v_item_pieces, 0), COALESCE(NEW.produced, 0));
      NEW.pieces_quantity := COALESCE(NULLIF(NEW.pieces_quantity, 0), NULLIF(v_item_pieces, 0), v_realized);
    END IF;
  END IF;

  NEW.realized_quantity := COALESCE(v_realized, 0);
  v_base := COALESCE(NULLIF(NEW.planned_target, 0), NULLIF(NEW.planned_capacity, 0), 0);
  NEW.difference_quantity := NEW.realized_quantity - v_base;
  NEW.efficiency_percent := CASE WHEN COALESCE(NEW.planned_target, 0) > 0
    THEN ROUND((NEW.realized_quantity / NEW.planned_target) * 100, 1)
    ELSE 0
  END;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.enrich_rejected_reading_context()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_piece public.production_pieces%ROWTYPE;
  v_lot public.production_lots%ROWTYPE;
  v_order public.production_orders%ROWTYPE;
  v_event public.production_collection_events%ROWTYPE;
BEGIN
  IF NEW.status <> 'rejected' OR NEW.piece_id IS NULL THEN RETURN NEW; END IF;

  SELECT * INTO v_piece FROM public.production_pieces WHERE id = NEW.piece_id;
  SELECT * INTO v_lot FROM public.production_lots WHERE id = v_piece.lot_id;
  SELECT * INTO v_order
  FROM public.production_orders
  WHERE id = COALESCE(v_piece.production_order_id, v_lot.production_order_id, v_lot.order_id);
  SELECT * INTO v_event
  FROM public.production_collection_events
  WHERE piece_id = v_piece.id
  ORDER BY created_at DESC
  LIMIT 1;

  NEW.event_type := 'rejected_scan';
  NEW.tag_value := COALESCE(NULLIF(NEW.tag_value, ''), v_piece.traceability_code, v_piece.piece_uid);
  NEW.piece_code := COALESCE(NULLIF(NEW.piece_code, ''), v_piece.piece_code,
                             v_piece.traceability_code, v_piece.piece_uid);
  NEW.lot_id := COALESCE(NEW.lot_id, v_piece.lot_id);
  NEW.production_order_id := COALESCE(NEW.production_order_id, v_piece.production_order_id,
                                      v_lot.production_order_id, v_lot.order_id);
  NEW.lot_code := COALESCE(NULLIF(NEW.lot_code, ''), NULLIF(v_piece.lot_code, ''),
                           NULLIF(v_event.lot_code, ''), v_lot.lot_code);
  NEW.order_number := COALESCE(NULLIF(NEW.order_number, ''), NULLIF(v_piece.order_number, ''),
                                NULLIF(v_event.order_number, ''), v_order.order_number, v_order.order_code);
  NEW.customer_name := COALESCE(NULLIF(NEW.customer_name, ''), NULLIF(v_piece.customer_name, ''),
                                 NULLIF(v_event.customer_name, ''), v_order.customer_name);
  NEW.environment_name := COALESCE(NULLIF(NEW.environment_name, ''),
                                    NULLIF(v_piece.environment_name, ''),
                                    NULLIF(v_piece.environment, ''),
                                    NULLIF(v_event.environment_name, ''), 'Geral / Produção');
  NEW.step_name := COALESCE(NULLIF(NEW.step_name, ''), NULLIF(v_event.operation_name, ''),
                            NULLIF(v_piece.current_stage, ''), 'Coleta');
  NEW.operation_name := COALESCE(NULLIF(NEW.operation_name, ''), NEW.step_name);
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.enrich_replacement_order_context()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_piece public.production_pieces%ROWTYPE;
  v_lot public.production_lots%ROWTYPE;
  v_order public.production_orders%ROWTYPE;
  v_event public.production_collection_events%ROWTYPE;
  v_stage text;
  v_general_lot text;
BEGIN
  IF NEW.original_piece_id IS NULL THEN RETURN NEW; END IF;

  SELECT * INTO v_piece
  FROM public.production_pieces
  WHERE id = NEW.original_piece_id;
  IF v_piece.id IS NULL THEN RETURN NEW; END IF;

  SELECT * INTO v_lot FROM public.production_lots WHERE id = v_piece.lot_id;
  SELECT * INTO v_order
  FROM public.production_orders
  WHERE id = COALESCE(v_piece.production_order_id, v_lot.production_order_id, v_lot.order_id);
  SELECT * INTO v_event
  FROM public.production_collection_events
  WHERE piece_id = v_piece.id
  ORDER BY created_at DESC
  LIMIT 1;

  SELECT r.step_name INTO v_stage
  FROM public.production_stage_readings r
  WHERE r.piece_id = v_piece.id
    AND r.status IN ('pending_review', 'rejected', 'approved')
  ORDER BY CASE r.status WHEN 'pending_review' THEN 0 WHEN 'rejected' THEN 1 ELSE 2 END,
           r.created_at DESC
  LIMIT 1;

  v_general_lot := NULLIF(v_event.general_lot_code, '');
  IF v_general_lot IS NULL AND v_piece.pcp_import_batch_id IS NOT NULL THEN
    SELECT general_lot_code INTO v_general_lot
    FROM public.promob_import_batches
    WHERE id = v_piece.pcp_import_batch_id;
  END IF;

  NEW.lot_id := COALESCE(NEW.lot_id, v_piece.lot_id);
  NEW.production_order_id := COALESCE(NEW.production_order_id, v_piece.production_order_id,
                                      v_lot.production_order_id, v_lot.order_id);
  NEW.lot_code := COALESCE(NULLIF(NEW.lot_code, ''), NULLIF(v_piece.lot_code, ''),
                           NULLIF(v_event.lot_code, ''), v_lot.lot_code);
  NEW.general_lot_code := COALESCE(NULLIF(NEW.general_lot_code, ''), v_general_lot);
  NEW.order_number := COALESCE(NULLIF(NEW.order_number, ''), NULLIF(v_piece.order_number, ''),
                                NULLIF(v_event.order_number, ''), v_order.order_number, v_order.order_code);
  NEW.customer_name := COALESCE(NULLIF(NEW.customer_name, ''), NULLIF(v_piece.customer_name, ''),
                                 NULLIF(v_event.customer_name, ''), v_order.customer_name);
  NEW.environment_name := COALESCE(NULLIF(NEW.environment_name, ''),
                                    NULLIF(v_piece.environment_name, ''),
                                    NULLIF(v_piece.environment, ''),
                                    NULLIF(v_event.environment_name, ''), 'Geral / Produção');
  NEW.operator_id := COALESCE(NEW.operator_id, v_event.operator_id);
  NEW.operator_name := COALESCE(NULLIF(NEW.operator_name, ''), NULLIF(v_event.operator_name, ''));
  NEW.origin_cell_name := COALESCE(NULLIF(NEW.origin_cell_name, ''), NULLIF(v_event.cell_name, ''));
  NEW.rejection_stage := CASE
    WHEN NEW.rejection_stage IS NULL
      OR lower(NEW.rejection_stage) IN ('concluída', 'concluida', 'completed', 'created')
      THEN COALESCE(NULLIF(v_stage, ''), NULLIF(v_event.operation_name, ''),
                    NULLIF(v_piece.current_stage, ''), 'Corte')
    ELSE NEW.rejection_stage
  END;
  NEW.updated_at := now();
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.enrich_stage_reading_context()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  SELECT COALESCE(production_order_id, order_id) INTO NEW.production_order_id FROM production_lots WHERE id = NEW.lot_id;
  IF NEW.order_item_id IS NULL THEN
    SELECT poi.id INTO NEW.order_item_id FROM production_order_items poi
    LEFT JOIN production_lot_items pli ON pli.id = NEW.item_id
    WHERE poi.lot_id = NEW.lot_id AND (pli.id IS NULL OR poi.product_code = pli.product_code OR poi.product_name = pli.product_name)
    ORDER BY poi.created_at LIMIT 1;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.finish_production_downtime(p_occurrence_id uuid, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_occ record;
  v_ended_at timestamptz := COALESCE((p_payload->>'ended_at')::timestamptz, now());
  v_duration numeric;
  v_notes text := p_payload->>'notes';
BEGIN
  SELECT * INTO v_occ FROM public.occurrences WHERE id = p_occurrence_id;
  IF v_occ IS NULL THEN
    RAISE EXCEPTION 'Ocorrência de parada não encontrada.';
  END IF;

  IF v_occ.status = 'resolved' AND v_occ.ended_at IS NOT NULL THEN
    RETURN jsonb_build_object('success', true, 'already_finished', true, 'duration_minutes', v_occ.duration_minutes);
  END IF;

  -- Calcular duração em minutos no banco de dados
  v_duration := ROUND(EXTRACT(EPOCH FROM (v_ended_at - COALESCE(v_occ.started_at, v_occ.created_at))) / 60.0, 2);
  IF v_duration < 0 THEN
    v_duration := 0;
  END IF;

  UPDATE public.occurrences
  SET ended_at = v_ended_at,
      duration_minutes = v_duration,
      downtime = v_duration, -- Manter campo legado sincronizado
      status = 'resolved',
      notes = CASE WHEN v_notes IS NOT NULL THEN COALESCE(notes, '') || ' | Encerramento: ' || v_notes ELSE notes END,
      updated_at = now()
  WHERE id = p_occurrence_id;

  RETURN jsonb_build_object(
    'success', true,
    'occurrence_id', p_occurrence_id,
    'status', 'resolved',
    'duration_minutes', v_duration,
    'ended_at', v_ended_at
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.force_complete_piece_replacement(p_order_id uuid, p_reason text, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_order public.replacement_orders%ROWTYPE;
  v_user_role text;
BEGIN
  v_user_role := public.get_my_role();
  IF v_user_role NOT IN ('admin', 'manager') THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Apenas administradores e gestores podem realizar a conclusão forçada de reposições.'
    );
  END IF;

  IF TRIM(COALESCE(p_reason, '')) = '' THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'É obrigatório informar a justificativa para a conclusão forçada.'
    );
  END IF;

  SELECT * INTO v_order
  FROM public.replacement_orders
  WHERE id = p_order_id FOR UPDATE;

  IF v_order.id IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Ordem de reposição não localizada.'
    );
  END IF;

  UPDATE public.replacement_orders
  SET status = 'completed',
      completed_at = now(),
      notes = COALESCE(notes, '') || format(' [Conclusão forçada por %s: %s]', auth.uid(), p_reason),
      updated_at = now()
  WHERE id = v_order.id;

  IF v_order.replacement_piece_id IS NOT NULL THEN
    UPDATE public.production_pieces
    SET status = 'completed',
        current_stage = 'Concluída',
        updated_at = now()
    WHERE id = v_order.replacement_piece_id;
  END IF;

  IF v_order.original_piece_id IS NOT NULL THEN
    UPDATE public.production_pieces
    SET status = 'replaced',
        updated_at = now()
    WHERE id = v_order.original_piece_id;
  END IF;

  INSERT INTO public.audit_logs (
    action,
    entity,
    entity_id,
    details,
    created_at
  ) VALUES (
    'replacement_force_completed',
    'replacement_orders',
    v_order.id,
    jsonb_build_object(
      'replacement_code', v_order.replacement_code,
      'reason', p_reason,
      'forced_by', auth.uid()
    ),
    now()
  );

  RETURN jsonb_build_object(
    'success', true,
    'message', 'Conclusão forçada registrada com sucesso e auditada.'
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.generate_piece_uid()
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_date  text := to_char(now(), 'YYYYMMDD');
  v_rand  text := upper(substring(encode(extensions.gen_random_bytes(4), 'hex') FROM 1 FOR 6));
  v_uid   text;
BEGIN
  v_uid := 'PC-' || v_date || '-' || v_rand;
  WHILE EXISTS (SELECT 1 FROM production_pieces WHERE piece_uid = v_uid) LOOP
    v_rand := upper(substring(encode(extensions.gen_random_bytes(4), 'hex') FROM 1 FOR 6));
    v_uid  := 'PC-' || v_date || '-' || v_rand;
  END LOOP;
  RETURN v_uid;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_ai_capability_context()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_role text;
  v_permissions jsonb := '{}'::jsonb;
  v_capabilities jsonb;
begin
  if auth.uid() is null then
    raise exception 'AUTH_REQUIRED';
  end if;

  select p.role, coalesce(p.permissions, '{}'::jsonb)
  into v_role, v_permissions
  from public.profiles p
  where p.id = auth.uid()
    and p.active is distinct from false;

  if v_role is null then
    raise exception 'ACCESS_DENIED';
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'code', c.code,
        'label', c.label,
        'description', c.description,
        'actions', c.actions,
        'routes', c.routes,
        'metadata', c.metadata
      )
      order by c.code
    ),
    '[]'::jsonb
  )
  into v_capabilities
  from public.ai_capabilities c
  where c.active
    and (
      v_role in ('admin', 'manager')
      or cardinality(c.required_permissions) = 0
      or exists (
        select 1
        from unnest(c.required_permissions) permission_name
        where lower(coalesce(v_permissions ->> permission_name, 'false')) in ('true', '1')
      )
    );

  return jsonb_build_object(
    'generatedAt', now(),
    'role', v_role,
    'capabilities', v_capabilities
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.get_client_lot_progress(p_lot_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_lot record;
  v_total_parts bigint := 0;
  v_completed_parts bigint := 0;
  v_total_operations bigint := 0;
  v_completed_operations bigint := 0;
  v_progress_percent numeric(5,2) := 0;
BEGIN
  SELECT * INTO v_lot FROM public.production_lots WHERE id = p_lot_id;
  IF v_lot.id IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT
    count(*),
    count(*) FILTER (WHERE p.status IN ('completed','packed','inspected','ready_for_shipping','shipped')),
    COALESCE(sum(cardinality(COALESCE(p.route_steps, '{}'::text[]))), 0),
    COALESCE(sum(cardinality(ARRAY(
      SELECT DISTINCT step
      FROM unnest(COALESCE(p.route_steps, '{}'::text[])) AS step
      WHERE step = ANY(COALESCE(p.completed_steps, '{}'::text[]))
    ))), 0)
  INTO v_total_parts, v_completed_parts, v_total_operations, v_completed_operations
  FROM public.production_pieces p
  WHERE p.lot_id = p_lot_id
    AND p.status NOT IN ('cancelled','replaced');

  v_progress_percent := CASE
    WHEN v_total_operations > 0 THEN ROUND((v_completed_operations::numeric / v_total_operations::numeric) * 100, 2)
    ELSE 0.0
  END;

  RETURN jsonb_build_object(
    'lot_id', p_lot_id,
    'lot_code', v_lot.lot_code,
    'total_parts', v_total_parts,
    'completed_parts', v_completed_parts,
    'pending_parts', GREATEST(v_total_parts - v_completed_parts, 0),
    'total_operations', v_total_operations,
    'completed_operations', v_completed_operations,
    'progress_percent', LEAST(GREATEST(v_progress_percent, 0), 100)
  );
END;
$function$

