CREATE OR REPLACE FUNCTION public.get_general_lot_tracking(p_batch_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 25)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  payload jsonb;
  route_progress jsonb;
  general_lots jsonb := '[]'::jsonb;
  client_lots jsonb;
  general_lot jsonb;
  client_lot jsonb;
  lot_stages jsonb;
  traceable_required integer;
  traceable_completed integer;
  route_complete boolean;
begin
  payload := public.get_general_lot_tracking_base(p_batch_id, p_limit);

  -- A listagem geral não traz lotes de clientes e deve continuar leve. A rota
  -- completa é anexada apenas quando um lote geral é aberto.
  if p_batch_id is null then
    return payload;
  end if;

  for general_lot in
    select item.value
    from jsonb_array_elements(
      coalesce(payload->'general_lots', '[]'::jsonb)
    ) item(value)
  loop
    route_progress := public.get_lot_route_stage_progress(
      (general_lot->>'batch_id')::uuid
    );
    client_lots := '[]'::jsonb;

    for client_lot in
      select item.value
      from jsonb_array_elements(
        coalesce(general_lot->'client_lots', '[]'::jsonb)
      ) item(value)
    loop
      lot_stages := coalesce(
        route_progress->'lot_stages'->(client_lot->>'lot_id'),
        '[]'::jsonb
      );

      if jsonb_array_length(lot_stages) > 0 then
        select
          coalesce(sum(
            coalesce((stage.value->>'required_pieces')::integer, 0)
          ) filter (
            where coalesce(
              (stage.value->>'traceable_collection_required')::boolean,
              true
            )
          ), 0)::integer,
          coalesce(sum(
            least(
              coalesce((stage.value->>'required_pieces')::integer, 0),
              coalesce(
                (stage.value->>'effective_completed_pieces')::integer,
                (stage.value->>'completed_pieces')::integer,
                0
              )
            )
          ) filter (
            where coalesce(
              (stage.value->>'traceable_collection_required')::boolean,
              true
            )
          ), 0)::integer,
          coalesce(bool_and(
            case
              when coalesce(
                (stage.value->>'traceable_collection_required')::boolean,
                true
              )
              and coalesce((stage.value->>'required_pieces')::integer, 0) > 0
              then coalesce(
                (stage.value->>'effective_completed_pieces')::integer,
                (stage.value->>'completed_pieces')::integer,
                0
              ) >= coalesce((stage.value->>'required_pieces')::integer, 0)
              else true
            end
          ), false)
          into traceable_required, traceable_completed, route_complete
        from jsonb_array_elements(lot_stages) stage(value);

        client_lot := client_lot || jsonb_build_object(
          'stages', lot_stages,
          'total_operations', traceable_required,
          'completed_operations', traceable_completed,
          'progress_percent', case
            when traceable_required > 0
              then round(100.0 * traceable_completed / traceable_required, 2)
            else 100.0
          end,
          'ready_for_separation', route_complete
        );
      end if;

      client_lots := client_lots || jsonb_build_array(client_lot);
    end loop;

    select
      coalesce(sum(
        coalesce((stage.value->>'required_pieces')::integer, 0)
      ) filter (
        where coalesce(
          (stage.value->>'traceable_collection_required')::boolean,
          true
        )
      ), 0)::integer,
      coalesce(sum(
        least(
          coalesce((stage.value->>'required_pieces')::integer, 0),
          coalesce(
            (stage.value->>'effective_completed_pieces')::integer,
            (stage.value->>'completed_pieces')::integer,
            0
          )
        )
      ) filter (
        where coalesce(
          (stage.value->>'traceable_collection_required')::boolean,
          true
        )
      ), 0)::integer,
      coalesce(bool_and(
        case
          when coalesce(
            (stage.value->>'traceable_collection_required')::boolean,
            true
          )
          and coalesce((stage.value->>'required_pieces')::integer, 0) > 0
          then coalesce(
            (stage.value->>'effective_completed_pieces')::integer,
            (stage.value->>'completed_pieces')::integer,
            0
          ) >= coalesce((stage.value->>'required_pieces')::integer, 0)
          else true
        end
      ), false)
      into traceable_required, traceable_completed, route_complete
    from jsonb_array_elements(
      coalesce(route_progress->'batch_stages', '[]'::jsonb)
    ) stage(value);

    general_lot := general_lot || jsonb_build_object(
      'stages', coalesce(route_progress->'batch_stages', '[]'::jsonb),
      'client_lots', client_lots,
      'total_operations', traceable_required,
      'completed_operations', traceable_completed,
      'progress_percent', case
        when traceable_required > 0
          then round(100.0 * traceable_completed / traceable_required, 2)
        else 100.0
      end,
      'ready_for_separation', route_complete
    );

    general_lots := general_lots || jsonb_build_array(general_lot);
  end loop;

  return jsonb_set(payload, '{general_lots}', general_lots, true);
end;
$function$

CREATE OR REPLACE FUNCTION public.get_promob_token(integration_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
DECLARE
  secret_id uuid;
  decrypted text;
BEGIN
  SELECT token_reference::uuid INTO secret_id FROM promob_integrations WHERE id = integration_id;

  IF secret_id IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT decrypted_secret INTO decrypted FROM vault.decrypted_secrets WHERE id = secret_id;
  RETURN decrypted;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_replacement_approval_cells(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_context jsonb;
  v_order public.replacement_orders%ROWTYPE;
  v_original public.production_pieces%ROWTYPE;
  v_route text[];
  v_cells jsonb;
BEGIN
  v_context := public.get_replacement_order_context(p_order_id);

  SELECT * INTO v_order
  FROM public.replacement_orders
  WHERE id = p_order_id;

  SELECT * INTO v_original
  FROM public.production_pieces
  WHERE id = v_order.original_piece_id;

  v_route := COALESCE(v_original.route_steps, '{}'::text[]);
  IF cardinality(v_route) = 0 THEN
    v_route := ARRAY[]::text[];
    IF COALESCE(v_original.requires_cut, false) THEN v_route := array_append(v_route, 'cut'); END IF;
    IF COALESCE(v_original.requires_edge, false) THEN v_route := array_append(v_route, 'edge'); END IF;
    IF COALESCE(v_original.requires_cnc, false) THEN v_route := array_append(v_route, 'cnc'); END IF;
    IF COALESCE(v_original.requires_joinery, false) THEN v_route := array_append(v_route, 'joinery'); END IF;
    IF COALESCE(v_original.requires_separation, false) THEN v_route := array_append(v_route, 'separation'); END IF;
    IF COALESCE(v_original.requires_packaging, false) THEN v_route := array_append(v_route, 'packaging'); END IF;
  END IF;

  WITH route AS (
    SELECT
      r.ordinality,
      r.raw_step,
      public.normalize_replacement_step_code(r.raw_step) AS step_code
    FROM unnest(v_route) WITH ORDINALITY AS r(raw_step, ordinality)
  ), eligible AS (
    SELECT
      route.ordinality,
      c.id AS cell_id,
      c.name AS cell_name,
      route.step_code,
      COALESCE(rs.name, route.raw_step, c.name) AS step_name,
      (
        public.normalize_replacement_step_code(v_order.rejection_stage) = route.step_code
        OR lower(trim(COALESCE(v_order.origin_cell_name, ''))) = lower(trim(c.name))
      ) AS is_rejection_stage
    FROM route
    LEFT JOIN public.routing_steps rs ON rs.code = route.step_code
    JOIN public.cells c
      ON c.active IS TRUE
     AND public.replacement_cell_matches_step(c.name, route.step_code)
  )
  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'selection_key', eligible.cell_id::text || ':' || eligible.step_code,
        'cell_id', eligible.cell_id,
        'cell_name', eligible.cell_name,
        'step_code', eligible.step_code,
        'step_name', eligible.step_name,
        'is_rejection_stage', eligible.is_rejection_stage
      ) ORDER BY eligible.ordinality
    ),
    '[]'::jsonb
  )
  INTO v_cells
  FROM eligible;

  RETURN v_context || jsonb_build_object(
    'route_steps', to_jsonb(v_route),
    'cells', v_cells
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.get_replacement_order_context_impl(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_order public.replacement_orders%ROWTYPE;
  v_original public.production_pieces%ROWTYPE;
  v_replacement public.production_pieces%ROWTYPE;
  v_lot public.production_lots%ROWTYPE;
  v_production_order public.production_orders%ROWTYPE;
  v_production_order_id uuid;
  v_lot_code text;
  v_general_lot_code text;
  v_order_number text;
  v_customer_name text;
  v_environment_name text;
  v_barcode text;
  v_route text[];
  v_order_json jsonb;
  v_original_json jsonb;
  v_replacement_json jsonb;
BEGIN
  SELECT * INTO v_order
  FROM public.replacement_orders
  WHERE id = p_order_id;

  IF v_order.id IS NULL THEN
    RAISE EXCEPTION 'Ordem de reposição não encontrada.';
  END IF;

  SELECT * INTO v_original
  FROM public.production_pieces
  WHERE id = v_order.original_piece_id;

  IF v_original.id IS NULL THEN
    RAISE EXCEPTION 'A ordem % não possui peça original válida.', COALESCE(v_order.replacement_code, v_order.id::text);
  END IF;

  IF v_order.replacement_piece_id IS NOT NULL THEN
    SELECT * INTO v_replacement
    FROM public.production_pieces
    WHERE id = v_order.replacement_piece_id;
  END IF;

  IF v_original.lot_id IS NOT NULL THEN
    SELECT * INTO v_lot
    FROM public.production_lots
    WHERE id = v_original.lot_id;
  END IF;

  v_production_order_id := COALESCE(
    v_original.production_order_id,
    v_lot.production_order_id,
    v_lot.order_id,
    v_order.production_order_id
  );

  IF v_production_order_id IS NOT NULL THEN
    SELECT * INTO v_production_order
    FROM public.production_orders
    WHERE id = v_production_order_id;
  END IF;

  v_lot_code := COALESCE(
    NULLIF(v_original.lot_code, ''),
    NULLIF(v_lot.lot_code, ''),
    NULLIF(v_order.lot_code, '')
  );
  v_general_lot_code := COALESCE(
    NULLIF(v_lot.general_lot_code, ''),
    NULLIF(v_order.general_lot_code, '')
  );
  v_order_number := COALESCE(
    NULLIF(v_original.order_number, ''),
    NULLIF(v_production_order.order_number, ''),
    NULLIF(v_production_order.order_code, ''),
    NULLIF(v_lot.order_number, ''),
    NULLIF(v_order.order_number, '')
  );
  v_customer_name := COALESCE(
    NULLIF(v_original.customer_name, ''),
    NULLIF(v_production_order.customer_name, ''),
    NULLIF(v_lot.customer_name, ''),
    NULLIF(v_order.customer_name, '')
  );
  v_environment_name := COALESCE(
    NULLIF(v_original.environment_name, ''),
    NULLIF(v_original.environment, ''),
    NULLIF(v_order.environment_name, '')
  );
  v_barcode := COALESCE(
    NULLIF(v_order.replacement_barcode, ''),
    NULLIF(v_original.traceability_code, ''),
    NULLIF(v_original.piece_uid, ''),
    NULLIF(v_original.piece_code, '')
  );
  v_route := COALESCE(v_original.route_steps, '{}'::text[]);

  v_order_json := to_jsonb(v_order) || jsonb_build_object(
    'lot_id', v_original.lot_id,
    'production_order_id', v_production_order_id,
    'lot_code', v_lot_code,
    'general_lot_code', v_general_lot_code,
    'order_number', v_order_number,
    'customer_name', v_customer_name,
    'environment_name', v_environment_name
  );

  v_original_json := to_jsonb(v_original) || jsonb_build_object(
    'lot_code', v_lot_code,
    'general_lot_code', v_general_lot_code,
    'order_number', v_order_number,
    'customer_name', v_customer_name,
    'environment_name', v_environment_name,
    'lot', CASE WHEN v_lot.id IS NULL THEN NULL ELSE to_jsonb(v_lot) END,
    'production_order', CASE WHEN v_production_order.id IS NULL THEN NULL ELSE to_jsonb(v_production_order) END
  );

  v_replacement_json := CASE
    WHEN v_replacement.id IS NULL THEN NULL
    ELSE to_jsonb(v_replacement) || jsonb_build_object(
      'lot_code', v_lot_code,
      'general_lot_code', v_general_lot_code,
      'order_number', v_order_number,
      'customer_name', v_customer_name,
      'environment_name', v_environment_name
    )
  END;

  RETURN jsonb_build_object(
    'order', v_order_json,
    'original_piece', v_original_json,
    'replacement_piece', v_replacement_json,
    'replacement_code', v_order.replacement_code,
    'barcode', v_barcode,
    'route_steps', to_jsonb(v_route),
    'integrity', jsonb_build_object(
      'order_id', v_order.id,
      'original_piece_id', v_order.original_piece_id,
      'resolved_piece_id', v_original.id,
      'piece_link_valid', v_order.original_piece_id = v_original.id,
      'lot_link_valid', v_order.lot_id IS NULL OR v_order.lot_id = v_original.lot_id
    )
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.get_replacement_order_context(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_origin_cell text;
begin
  select origin_cell_name into v_origin_cell
  from public.replacement_orders
  where id = p_order_id;

  if not found then
    raise exception 'Ordem de reposição não encontrada.';
  end if;

  if auth.role() <> 'service_role'
     and not (
       public.has_permission('view_replacements')
       or public.has_permission('manage_replacements')
       or public.has_permission('approve_replacements')
       or public.has_permission('view_quality')
       or public.has_permission('manage_quality')
     ) then
    raise exception 'REPLACEMENT_VIEW_PERMISSION_REQUIRED' using errcode = '42501';
  end if;

  if auth.role() <> 'service_role'
     and v_origin_cell is not null
     and not public.profile_can_access_cell(v_origin_cell) then
    raise exception 'REPLACEMENT_OUTSIDE_CELL_SCOPE' using errcode = '42501';
  end if;

  return public.get_replacement_order_context_impl(p_order_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.get_replacement_station_queue_v3(p_session_token text, p_device_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
AS $function$
declare
  v_access jsonb;
begin
  v_access := private.validate_replacement_operator_session_v2(p_session_token, p_device_id, true);
  if coalesce((v_access ->> 'success')::boolean, false) is not true then
    return v_access;
